['The task you've asked for is quite complex and involves several components such as multi-threading, networking, data parsing, JSON serialization/deserialization, logging framework etc. 

Here's a simplified example of how it can be implemented using libcurl for network requests, cJSON for JSON manipulation, POSIX threads for concurrency and glibc for miscellaneous utilities:

```C
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include "curl/curl.h"
#include "cJSON.h"

// Defined as macros to make them easier to change later on
#define MAX_THREADS 10
#define API_URL "https://api.example.com/"

typedef struct {
    char* message;
    int severity;
} LogEntry;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
CURL *curl;
struct curl_slist *headers = NULL;
cJSON *json;
FILE *logFile;
char errorBuffer[CURL_ERROR_SIZE];
int stillRunning = 0;

void* logProcessor(void* arg) {
    LogEntry *entry = (LogEntry*)arg;

    pthread_mutex_lock(&lock);

    // Parsing the log entry and filtering it based on severity, source etc.
    if(entry->severity > 5) {
        fprintf(logFile, "%s\n", entry->message);

        json = cJSON_CreateObject();
        cJSON_AddStringToObject(json, "message", entry->message);
        char *renderedJson = cJSON_PrintUnformatted(json);

        // Use libcurl to send the JSON data to remote API
        curl_easy_setopt(curl, CURLOPT_URL, API_URL);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, renderedJson);

        if (curl_easy_perform(curl) != CURLE_OK) {
            fprintf(stderr, "Failed to send log data: %s\n", errorBuffer);
        }
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    curl = curl_easy_init();
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, errorBuffer);

    logFile = fopen("log.txt", "a");
    pthread_t threads[MAX_THREADS];

    // Assuming logs are read from some external data source and put into an array for this example
    LogEntry *logs; 
    int numLogs = 0; // Get the number of log entries from your data source

    for(int i=0; i<numLogs && i<MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, &logProcessor, (void*)&logs[i]);
    }

    for(int i=0; i<numLogs && i<MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    fclose(logFile);
    curl_easy_cleanup(curl);
}
```

Please note this is a very simplified version. You might want to split the code into modules, use data structures and algorithms that are suitable for your task, add more sophisticated error handling, metrics collection etc. 

Also please make sure you have the libcurl (https://curl.se/libcurl/) and cJSON (https://github.com/DaveGamble/cJSON) libraries installed in order to compile this code. You'll also need a valid API_URL for logging data, replace 'https://api.example.com/' with your actual remote logging API URL.
']

