import os
import json
import hashlib
import argparse
from random import SystemRandom
from threading import Lock
import logging
from functools import wraps

# Load configuration from a file
def load_config(filepath):
    with open(filepath, 'r') as f:
        config = json.load(f)
    return config

# Save configuration to a file
def save_config(filepath, config):
    with open(filepath, 'w') as f:
        json.dump(config, f, indent=4)

# Securely hash an API key
def secure_hash(key):
    return hashlib.sha256(key.encode()).hexdigest()

# Check if an environment variable is set for a given key
def check_env(key):
    return os.getenv(key) is not None

# Securely generate an API key
secure_random = SystemRandom()
def secure_generate_api_key():
    return ''.join(secure_random.choice('0123456789ABCDEF') for _ in range(16))

class ConfigManager:
    def __init__(self, filepath):
        self.filepath = filepath
        self.config = load_config(filepath)
        self.lock = Lock()  # Ensure concurrent access is safe

    @log_execution
    def insert_api_key(self, key):
        hashed_key = secure_hash(key)
        self.config['API_KEY'] = hashed_key

    @log_execution
    def update_environment(self, env):
        if check_env(env):
            # Use environment variable to override configuration
            self.config['ENVIRONMENT'] = os.getenv(env)

    def save_changes(self):
        with self.lock:  # Ensure atomicity of write operations
            save_config(self.filepath, self.config)
```
