    EncryptionService* service = initialize_service(cipher_algo, kms);

    // Simultaneously encrypt and decrypt data using threading.
    pthread_t threads[2];

    int i;
    for (i = 0; i < 2; i++) {
        if (pthread_create(&threads[i], NULL, i == 0 ? encrypt : decrypt, service)) {
            handle_error("Error creating thread");
        }
    }

    // Wait for both threads to complete.
    for (i = 0; i < 2; i++) {
        if (pthread_join(threads[i], NULL)) {
            handle_error("Error joining thread");
        }
    }

    return 0;
}
```
