['Here is a basic implementation of the `DatabaseExecutor` class in C#. This code doesn't cover every detail as per your requirement but it can serve as a good starting point. 

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

public class DatabaseExecutor : IDisposable
{
    private readonly ILogger<DatabaseExecutor> _logger;
    private readonly SqlConnectionStringBuilder _connectionStringBuilder;
    private readonly AsyncRetryPolicy _retryPolicy;
    private bool disposed = false;

    public DatabaseExecutor(IConfiguration config, ILogger<DatabaseExecutor> logger)
    {
        _logger = logger;

        // Read the connection string from configuration file or environment variables.
        var connectionString = config.GetConnectionString("DefaultConnection"); 
        _connectionStringBuilder = new SqlConnectionStringBuilder(connectionString);

        // Define a retry policy with exponential backoff for transient errors.
        _retryPolicy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)));
    }

    public async Task ExecuteParameterizedQueryAsync(string commandText, IEnumerable<SqlParameter> parameters)
    {
        using (var connection = new SqlConnection(_connectionStringBuilder.ToString()))
        using (var command = new SqlCommand(commandText, connection))
        {
            await connection.OpenAsync();

            // Add the parameters to the command.
            foreach (var parameter in parameters)
                command.Parameters.Add(parameter);

            _logger.LogInformation("Executing SQL command: {0}", commandText);

            // Execute the command with retry policy.
            await _retryPolicy.ExecuteAsync(async () =>
            {
                await command.ExecuteNonQueryAsync();
            });
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposed) 
            return;

        if (disposing) 
        {
            // Free any other managed objects here.
        }

        disposed = true;
    }
}
```
This code uses the `Microsoft.Extensions.Logging` for logging, `Polly` for retry policies and `System.Data.SqlClient` for database operations. It reads the connection string from a configuration file or environment variables. The `ExecuteParameterizedQueryAsync` method accepts an SQL command text and parameters, opens a database connection, executes the command with retries, and logs information about each operation. 

The code includes error handling that catches all exceptions (not recommended), which is a good starting point for robust error handling. The class also implements IDisposable to ensure proper resource management. 

Note: This is a simplified example and doesn't cover many important details such as transaction management, connection pooling, advanced error handling, etc. Also it needs additional improvements like connection string validation, exception handling (especially the SqlException), configuration file setup for logging etc. It is recommended to use ORM like Dapper or Entity Framework that already implements these features and provides a much more robust solution.
']

