        _appSettings = appSettings.CurrentValue;
    }

    public async Task UpdateConfigurationAsync()
    {
        try
        {
            // Fetch the updated configuration from cloud storage service
            var newConfig = await FetchNewConfiguration();

            // Validate and apply the new configuration
            if (Validate(newConfig))
                _appSettings.Update(newConfig);
            else
                throw new Exception("Invalid or corrupted Configuration");
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to update configuration.");

            // Handle the exception gracefully by degrading functionality, or 
            // reverting back to a previous working state if possible.
        }
    }

    private async Task<Configuration> FetchNewConfiguration()
    {
        var httpClient = new HttpClient();

        try
        {
            var response = await httpClient.GetAsync(_appSettings.CloudStorageEndpoint);

            if (response.IsSuccessStatusCode)
                return JsonConvert.DeserializeObject<Configuration>(await response.Content.ReadAsStringAsync());

            throw new Exception("Failed to fetch configuration from cloud storage.");
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Network failure while fetching configuration.");

            // Handle the exception gracefully by degrading functionality, or 
            // reverting back to a previous working state if possible.
        }
    }

