public class XmlProcessorService
{
    private readonly ILogger<XmlProcessorService> _logger;

    public XmlProcessorService(ILogger<XmlProcessorService> logger)
    {
        _logger = logger;
    }

    // Method to process XML documents
    public async Task ProcessAsync(XmlDocument xmlDoc, string xpathExpression)
    {
        try
        {
            var nodeList = xmlDoc.SelectNodes(xpathExpression);
            if (nodeList == null || nodeList.Count == 0)
                throw new InvalidOperationException("No matching element found.");

            // process the nodes asynchronously
            await ProcessNodeAsync(nodeList[0]).ConfigureAwait(false);
        }
        catch (XmlException ex)
        {
            _logger.LogError(ex, "XML parsing failed");
        }
    }

    // Method to process nodes asynchronously
    private async Task ProcessNodeAsync(XmlNode node)
    {
        // do something with the node...

        await Task.CompletedTask;
    }
}
```

In this example, we use `System.Threading.Tasks` for concurrency and asynchronous processing, allowing multiple clients to process XML documents simultaneously without blocking each other or consuming excessive resources. 

We also use dependency injection with the `Microsoft.Extensions.Logging` namespace for robust error handling and logging. The logger is used throughout the service to log details about any issues that arise during the processing of XML documents, helping debug and monitor the service's health and performance.

