            $stmt->bind_param('sssss', $userData['id'], $userData['name'], $userData['email'], $userData['password'], $sub_action);

            if(!$stmt->execute()){
                die('Execute failed: (' . $stmt->errno . ') ' . $stmt->error);
            }
        } else {
            // Handle invalid data.
        }
    }

    public function updateUser(array $userData, $sub_action) {
        $isValid = $this->validate($userData);

        if ($isValid) {
            $stmt = $this->db->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
            $stmt->bind_param('sssi', $userData['name'], $userData['email'], $userData['password'], $sub_action);

            if(!$stmt->execute()){
                die('Execute failed: (' . $stmt->errno . ') ' . $stmt->error);
            }
        } else {
            // Handle invalid data.
        }
