['Here is an example using Express for HTTP endpoints, Remark for markdown to HTML conversion, and Node-Cache for caching purposes:

```javascript
const express = require('express');
const fs = require('fs').promises;
const MarkdownIt = require('markdown-it')();
const NodeCache = require("node-cache");
const fetch = require('node-fetch');

// Initialize cache with a TTL of 10 minutes
const myCache = new NodeCache({ stdTTL: 600 });

const app = express();
app.use(express.json());

// Configuration options
let fileExtensionsToIgnore = ['.md']; // Default extensions to ignore
let processFileLimit = 10; // Default limit on files processed per request

// External API for metadata
const METADATA_API = 'https://example.com/api';

app.get('/markdown', async (req, res) => {
    try {
        const dirPath = req.query.dir; // Directory path from the query parameter

        if (!myCache.has(dirPath)) {
            console.log('Processing files...');

            let mdFiles = await fs.readdir(dirPath);
            mdFiles = mdFiles.filter(file => !fileExtensionsToIgnore.includes(file)); // Filter out the ignored extensions
            mdFiles = mdFiles.slice(0, processFileLimit); // Apply the limit on files processed

            const fileContents = await Promise.all(mdFiles.map(async file => {
                let content = await fs.readFile(`${dirPath}/${file}`, 'utf8');

                return { 
                    name: file, 
                    htmlContent: MarkdownIt.render(content), // Convert to HTML
                    metadata: (await fetchMetadata(file)) || {} // Fetch metadata from external API
                };
            }));

            myCache.set(dirPath, fileContents); // Cache the processed files
        } 

        res.json(myCache.get(dirPath));
    } catch (error) {
        console.error('Error processing files:', error);
        res.status(500).send({ error: 'An error occurred while processing the files.' });
    }
});

async function fetchMetadata(fileName) {
    try {
        const response = await fetch(`${METADATA_API}/${fileName}`); // Example API call
        if (!response.ok) throw new Error('Network response was not ok');

        return await response.json(); 
    } catch (error) {
        console.error('Error fetching metadata:', error);
        return null; // Return null or handle the error as per your requirement
    }
}

app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
```
This code provides a basic structure for processing Markdown files into HTML and serving them over HTTP endpoints. It utilizes caching to minimize repeated processing of the same directory and improve performance. Configuration options include file extensions to ignore and a limit on the number of files processed. The external API fetch is handled gracefully, returning null or a suitable error response upon failure. 

To fully understand trade-offs between performance, scalability, and user experience, you would need to conduct thorough tests with varying configurations and load scenarios. Additionally, robust unit and integration testing should be implemented to cover all edge cases and error scenarios. This code does not include these considerations due to its simplicity but it provides a good starting point for developing a more complete service.
']

