Remember to handle edge cases like concurrent loading of scripts for a large number of script objects to ensure the function remains performant even when processing thousands of scripts.
']

["Here's an example of how you might implement this service in AngularJS:

```javascript
(function() {
  'use strict';

  angular
    .module('app')
    .service('dialogFieldService', dialogFieldService);

  dialogFieldService.$inject = ['$http', '$q'];

  function dialogFieldService($http, $q) {
    var service = {
      refreshFields: refreshFields
    };

    return service;

    ////////////

    function refreshFields(resourceId, url, fieldNames) {
      var promises = [];

      angular.forEach(fieldNames, function(fieldName) {
        promises.push(refreshField(url + resourceId + '/' + fieldName));
      });

      return $q.all(promises).then(function(responses) {
        var oldTestamentBooks = {};

        angular.forEach(fieldNames, function(fieldName, index) {
          oldTestamentBooks[fieldName] = countOldTestamentMatches(responses[index].data);
        });

        return oldTestamentBooks;
      }).catch(function(error) {
        console.log('Error refreshing dialog fields: ', error);
        // Return fallback data or handle error appropriately
        return {};
      });
    }

    function refreshField(url) {
      return $http({
        method: 'GET',
        url: url,
        transformResponse: angular.identity  // To get raw text response
      });
    }

    function countOldTestamentMatches(content) {
      var oldTestamentBooks = ['Genesis', 'Exodus', /*... other books ...*/];
      var regexp = new RegExp('\\b(' + oldTestamentBooks.join('|') + ')\\b', 'g');

      var matches = content.match(regexp);
      return matches ? matches.length : 0;
    }
  }
})();
```
This is a simplified example and should be adapted to your specific use case, however it provides a solid foundation for building the service you described. Note that error handling could be improved upon as well as how resources are updated with new data in scope. For instance, this implementation assumes that the content of each field is plain text. In a real-world scenario, you might need to extract structured information from complex objects or HTML strings. 

