["Sure, here's an outline of how you might build such a system in Node.js:

```javascript
const express = require('express');
const fetch = require('node-fetch');
const LRU = require('lru-cache');
const async = require('async');

// Configure the server
const app = express();
app.use(express.json()); // for parsing application/json
app.use(express.urlencoded({ extended: true })); // for parsing application/x-www-form-urlencoded

// Set up an LRU cache for metadata and API responses
const cache = new LRU({ maxAge: 1000 * 60 * 60 }); // Cache for one hour

// Define the external APIs we're going to use
const apiEndpoints = ['http://api1.example.com', 'http://api2.example.com'];

app.post('/processDocument', async (req, res) => {
  const { url } = req.body;

  try {
    // Fetch the HTML document from the given URL
    const response = await fetch(url);
    const html = await response.text();

    // Process the HTML document asynchronously
    async.eachLimit(html, 10, (element, callback) => {
      getMetadataFromElement(element).then(() => {
        callback();
      }).catch((err) => {
        console.error(`Error processing element: ${err}`);
        callback();
      });
    }, err => {
      if (err) {
        res.status(500).send('An error occurred while processing the document');
      } else {
        res.send('Document processed successfully');
      }
    });
  } catch (error) {
    console.error(`Error fetching HTML: ${error}`);
    res.status(500).send('An error occurred while fetching the HTML document');
  }
});

async function getMetadataFromElement(element) {
  // Check if we've already retrieved metadata for this element from an API before
  const cached = cache.get(element);
  if (cached) {
    return cached;
  }

  // If not, fetch the data and store it in our cache
  for (let i = 0; i < apiEndpoints.length; i++) {
    const endpoint = apiEndpoints[i];

    try {
      const response = await fetch(`${endpoint}/metadata?element=${encodeURIComponent(element)}`);

      if (response.ok) {
        const metadata = await response.json();

        // Store the metadata in our cache
        cache.set(element, metadata);

        return metadata;
      } else {
        console.error(`Error fetching metadata from ${endpoint}: HTTP ${response.status}`);
      }
    } catch (error) {
      console.error(`Error fetching metadata from ${endpoint}: ${error}`);
    }
  }

  throw new Error('Unable to retrieve metadata for element');
}
```

This code sets up a simple Express server that accepts POST requests at `/processDocument`, which it uses to fetch an HTML document from the given URL. It then processes this document asynchronously, with each element being processed in parallel using async's `eachLimit` function and capped at 10 concurrent tasks. If an error occurs during processing, a message is logged and processing continues with other elements.

The `getMetadataFromElement` function fetches metadata for a given element from the external APIs we've defined. It first checks if it has this data cached locally; if not, it sends a request to each API in turn until one returns a successful response or all fail, at which point an error is thrown.

Please note that you would need to define your own `/metadata` endpoints on your APIs and properly handle errors. This code doesn't cover any of those details. Also, please replace the URLs in apiEndpoints with actual ones from where you want to fetch metadata.
"]

['This task involves many components and is quite complex, but here's a simplified example of how you can implement this using Node.js along with the request-promise library for http requests, and log4js for logging. 

Please note that this is just a basic outline and does not include all the mentioned features:

```javascript
const express = require('express');
const rp = require('request-promise');
const log4js = require('log4js');
const logger = log4js.getLogger();
logger.level = 'debug';

let config = {
  moduleMaxExecutionTime: 500, // in ms
};

let app = express();
app.use(express.json());

app.post('/loadModule', async (req, res) => {
  let start = Date.now();

  try{
    let options = {
      uri: req.body.moduleUrl,
      headers: {
        'User-Agent': 'Request-Promise'
      },
      json: true // Automatically parses the JSON string in the response
    };

    let moduleCode = await rp(options);
    let fn = new Function('exports',moduleCode);

    setTimeout(()=>{
        if((Date.now() - start) > config.moduleMaxExecutionTime){
          logger.warn(`Module from url: ${req.body.moduleUrl} took more than configured threshold to execute.`);
        }
      }, 
      config.moduleMaxExecutionTime+100 // Adding some buffer time for execution.
    );

    let module = {exports : {}};
    fn(module.exports);
    res.json({result: module.exports});
  }catch (err) {
    logger.error("Error loading or executing module: ", err);
    res.status(500).send('Module load/execution error');
  }
});

app.post('/configure', (req,res) => {
  config = Object.assign({},config, req.body);
  res.json({result: 'Configuration updated'});
});

const port = 8080;
app.listen(port, ()=>{ console.log(`Server running at http://localhost:${port}`)});
```
In this example, we use `express` for creating an API which can load and execute modules from external URLs. We use the `request-promise` library to make HTTP requests to fetch the module's code.

We use a setTimeout to check if the module execution time exceeds the configured threshold after some buffer time. If it does, we log a warning using `log4js`.

For testing, you can use frameworks like Jest or Mocha along with a tool like Supertest for making HTTP requests and asserting responses. 

This is just a skeleton implementation. A real-world application would require much more code to handle edge cases and complexities such as module dependencies, error tracking across multiple services, handling large scale deployments etc. Also, you need to take care about security concerns while implementing this. It's recommended to use only trusted third party endpoints for loading modules.
