    public void addDataset(List<Integer> dataset, int intervalInMilliseconds) {
        Runnable taskWrapper = () -> processBatch(dataset);
        scheduler.scheduleAtFixedRate(taskWrapper, 0, intervalInMilliseconds, TimeUnit.MILLISECONDS);
    }

    // Method to process a batch
    private void processBatch(List<Integer> elements) {
        long start = System.nanoTime();
        try {
