import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.handler.codec.http.HttpObjectAggregator;
import io.netty.handler.codec.http.HttpServerCodec;
import io.netty.handler.ssl.SslContextBuilder;
import io.netty.handler.ssl.util.SelfSignedCertificate;

public class NettyServer {
    private final int port;
    private EventLoopGroup bossGroup;
    private EventLoopGroup workerGroup;

    public NettyServer(int port) {
        this.port = port;
        start();
    }

    private void start() {
        SelfSignedCertificate ssc = new SelfSignedCertificate();
        SslContextBuilder context = GrpcSslContexts.forServer(ssc.certificate(), ssc.privateKey());

        bossGroup = new NioEventLoopGroup(1);
        workerGroup = new NioEventLoopGroup();

        try {
            ServerBootstrap b = new ServerBootstrap();

            b.group(bossGroup, workerGroup)
                .channel(NioServerSocketChannel.class)
                .handler(new LoggingHandler(LogLevel.INFO))
                .childHandler(new ChannelInitializer<SocketChannel>() {
                    @Override
                    protected void initChannel(SocketChannel ch) throws Exception {
                        ChannelPipeline p = ch.pipeline();

                        if (context != null) 
                            p.addLast(context.newHandler(ch.alloc()));

                        p.addLast(new HttpServerCodec());
                        p.addLast(new HttpObjectAggregator(512 * 1024));
                        p.addLast(new ServerHandler());
                    }
                });
            Channel ch = b.bind(port).sync().channel();
        } catch (Exception e) {
            // error handling here...
        }
    }

    public void stop() {
        bossGroup.shutdownGracefully();
        workerGroup.shutdownGracefully();
    }
}
```

The `ServerHandler` class would need to be implemented to handle incoming requests, perform authentication with the remote provider and logging services as required. The error handling in the above code is minimal, it's just an example for a starting point. It's important to add comprehensive exception handling based on your specific requirements. 

