```rust
use reqwest::{Client, Error};
use serde::Deserialize;
use std::error::Error as StdError;
use tokio::time::sleep;
use tokio::sync::Mutex;
use tokio::time::Duration;

#[derive(Debug, Deserialize)]
struct Response {
    // Define your response structure here.
}

pub struct MyClient {
    client: Mutex<Option<Client>>,
}

impl MyClient {
    pub async fn new() -> Result<Self, Error> {
        let client = Client::builder().build()?;
        Ok(MyClient{client: Mutex::new(Some(client))})
    }

    pub async fn get(&self, url: &str) -> Result<Response, Box<dyn StdError>> {
        let client = match self.client.lock().await {
            Ok(None) => return Err("Client not initialized".into()),
            Ok(Some(c)) => c,
            Err(_e) => return Err("Failed to lock client Mutex".into())
        };

        let response = match client.get(url).send().await {
            Ok(res) => res,
            Err(e) => return Err(formatErr(Box::new(e)))
        };

        match response.json::<Response>().await {
            Ok(r) => Ok(r),
            Err(e) => Err(formatErr(Box::new(e))),
        }
    }
}

fn main() -> Result<(), Box<dyn StdError>> {
    let client = MyClient::new().await?;

    loop {
        match client.get("http://example.com").await {
            Ok(res) => printlnSpaced(&formatResp(Box::new(res))),
            Err(e) => eprintlnSpaced(&formatErr(Box::new(e)), 3),
        };

        sleep(Duration::from_secs(1)).await;
    }
}
```

Please note this is a very basic example and does not cover all your requirements. To implement all of these features would require significant work in Rust, understanding of the libraries involved and deep knowledge of HTTP protocols, TLS encryption, OAuth2 tokens etc. It's recommended to have an experienced developer or team to design such a client properly.
