```php
<?php
class UserDao {
    private $dbConnection;
    // ... Connection details here ...

    public function updateUserPassword($userId, $newPassword, $retries = 3) {
        try {
            if (!$this->validateNewPassword($newPassword)) {
                throw new Exception("Invalid password");
            }

            $this->dbConnection->beginTransaction();

            // Repeat update in case of failure due to concurrency issues
            for ($i = 0; $i < $retries; ++$i) {
                $query = "UPDATE Users SET passwordHash=:passwordHash WHERE userId=:userId";
                $statement = $this->dbConnection->prepare($query);
                $hash = password_hash($newPassword, PASSWORD_DEFAULT); // Secure hash function
                $statement->bindParam(":passwordHash", $hash);
                $statement->bindParam(":userId", $userId);

                if ($statement->execute()) {
                    break;
                } elseif ($i < $retries - 1) {
                    // Wait before next retry, exponential backoff
                    sleep(pow(2, $i));
                } else {
                    throw new Exception("Failed to update password after retries");
                }
            }

            $this->dbConnection->commit();
        } catch (Exception $e) {
            // Logging mechanism here
            error_log($e->getMessage()); 

            if ($this->dbConnection->inTransaction()) {
                $this->dbConnection->rollBack();
            }

            throw $e;
        }
    }

    private function validateNewPassword($password) {
        $lengthValid = $this->validateMinimumLength($password);
        $complexityValid = $this->validateComplexity($password);
        $uniquenessValid = $this->validateUniqueness($password);

        return $lengthValid && $complexityValid && $uniquenessValid;
    }

