public interface IAuthenticationService
{
    Task<bool> AuthenticateUserAsync(string username, string password);
}

public class AuthenticationService : IAuthenticationService
{
    private readonly ILogger<AuthenticationService> _logger;
    private readonly IExternalApiClient _apiClient;

    public AuthenticationService(ILogger<AuthenticationService> logger, IExternalApiClient apiClient)
    {
        _logger = logger;
        _apiClient = apiClient;
    }

    public async Task<bool> AuthenticateUserAsync(string username, string password)
    {
        try
        {
            var hashedPassword = await ComputeHashAsync(password);
            return await _apiClient.AuthenticateAsync(username, hashedPassword);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while authenticating the user");
            throw;
        }
    }

    private async Task<string> ComputeHashAsync(string password)
    {
        using var md5 = MD5.Create();
        byte[] inputBytes = Encoding.ASCII.GetBytes(password);
        byte[] hashBytes = await Task.Run(() => md5.ComputeHash(inputBytes));

        return Convert.ToBase64String(hashBytes);
    }
}
```
