using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using Newtonsoft.Json;

public class DataProcessor
{
    private readonly Aes aesAlgorithm = Aes.Create();

    public async Task<T> ProcessDataAsync<T>(string filePath, string key)
    {
        var encryptedBytes = await ReadFromFileAsync(filePath);
        var decryptedBytes = DecryptData(encryptedBytes, Convert.FromBase64String(key));
        var serializedJson = Encoding.UTF8.GetString(decryptedBytes);

        return JsonConvert.DeserializeObject<T>(serializedJson);
    }

    private async Task<byte[]> ReadFromFileAsync(string filePath)
    {
        using var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read);
        var buffer = new byte[fs.Length];

        await fs.ReadAsync(buffer, 0, (int)fs.Length);

        return buffer;
    }

    private byte[] DecryptData(byte[] encryptedBytes, byte[] key)
    {
        aesAlgorithm.Key = key;

        var decryptor = aesAlgorithm.CreateDecryptor();
        var decryptedBytes = new List<byte>();

        for (int i = 0; i < encryptedBytes.Length; i += aesAlgorithm.BlockSize / 8)
        {
            var blockBytes = new byte[aesAlgorithm.BlockSize / 8];

            Array.Copy(encryptedBytes, i, blockBytes, 0, blockBytes.Length);

            var decryptedBlockBytes = TransformFinalBlock(decryptor, blockBytes);

            decryptedBytes.AddRange(decryptedBlockBytes);
        }

        return decryptedBytes.ToArray();
    }

    private byte[] TransformFinalBlock(ICryptoTransform transform, byte[] inputBuffer)
    {
        try
        {
            return transform.TransformFinalBlock(inputBuffer, 0, inputBuffer.Length);
        }
        catch (Exception ex)
        {
            // handle exception properly here...

            throw;
        }
    }
}
