async function modifyConfigFiles(configPaths, placeHolders, password) {
    let promises = [];

    configPaths.forEach(path => {
        let promise = new Promise((resolve, reject) => {
            fs.readFile(path, 'utf8', (err, data) => {
                if (err) {
                    reject("Error reading file " + path);
                } else {
                    Object.keys(placeHolders).forEach(key => {
                        let value = placeHolders[key];
                        while (data.indexOf(key) > -1) {
                            data = data.replace(key, value);
                        }
                    });
                    let encryptedPassword;

                    https.get('https://encryptionService/hash?password=' + password, (resp) => {
                        let data = '';

                        resp.on('data', (chunk) => {
                            data += chunk;
                        });

                        resp.on('end', () => {
                            encryptedPassword = data;

                            fs.appendFile(path, "\n" + encryptedPassword, function(err) {
                                if (err) reject("Error appending to file");
                                else resolve("Successfully updated " + path);
                            });
                        });

                    }).on('error', () => {
                        reject("Could not connect to encryption service.");
                    });
                }
            });
        });

        promises.push(promise);
    });

    let results = await Promise.allSettled(promises);

    // Logging the result to centralized monitoring service
    https.request(monitoringServiceUrl, { method: 'POST' }, (res) => {
        res.on('data', () => { /* empty */ });
    }).end(JSON.stringify({ configFilesPaths: results }));

    return results;
}

modifyConfigFiles(configFilesPaths, placeholdersValues, passwordToEncrypt)
    .then((results) => console.log(results))
    .catch((err) => console.error(err));
``` 

