```java
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

@RestController
public class UserProfileService {
    @Autowired
    private RedisTemplate<String, Object> redisTemplate;

    @Autowired
    private IdentityService identityService;

    @Autowired
    private ProfileRepository profileRepository;

    // Use cacheable for read-heavy operations to improve response times
    @Cacheable(value = "userProfiles", key = "#id")
    public UserProfile getUserProfile(String id) {
        return profileRepository.findById(id);
    }

    // PUT method to update a user's profile
    @PutMapping("/profile/{id}")
    public HttpStatus updateProfile(@PathVariable String id, @RequestBody UserProfile updatedProfile){
        if (identityService.authenticateUser(id)) { 
            UserProfile existingProfile = getUserProfile(id);

            // Use optimistic locking to handle race conditions
            if (existingProfile != null && existingProfile.getVersion() == updatedProfile.getVersion()) {
                profileRepository.save(updatedProfile);

                // Invalidate cache after update
                invalidateCache(id); 
                return HttpStatus.OK;
            } else {
                return HttpStatus.CONFLICT;
            }
        }

        return HttpStatus.UNAUTHORIZED;
    }

    // DELETE method to delete a user's profile
    @DeleteMapping("/profile/{id}")
    public HttpStatus deleteProfile(@PathVariable String id){
        if (identityService.authenticateUser(id)) {
            UserProfile existingProfile = getUserProfile(id);

            if (existingProfile != null) {
                profileRepository.deleteById(id);

                // Invalidate cache after deletion
                invalidateCache(id); 
                return HttpStatus.OK;
            } else {
                return HttpStatus.NOT_FOUND;
            }
        }

        return HttpStatus.UNAUTHORIZED;
    }

    // Use cache eviction for write operations to handle invalidating cache
    @CacheEvict(value = "userProfiles", key = "#id") 
