```C
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Structure for cipher context
typedef struct {
    EVP_CIPHER_CTX *ctx;
} AES256Context;

int init_cipher(const char *password, const unsigned char *salt, int iterations, AES256Context *aes) {
    // Initialize OpenSSL library
    OPENSSL_init();

    aes->ctx = EVP_CIPHER_CTX_new();
    if (aes->ctx == NULL) {
        return -1;  // Error initializing context
    }

    // Derive key from password using PBKDF2
    unsigned char derivedKey[32];  // AES-256 requires a 256 bit (32 byte) key
    if (!PKCS5_PBKDF2_HMAC(password, -1, salt, strlen((char *)salt), iterations, EVP_sha256(), 32, derivedKey)) {
        return -2;  // Error deriving key
    }

    // Initialize cipher context with AES-256-CBC mode
    if (!EVP_EncryptInit_ex(aes->ctx, EVP_aes_256_cbc(), NULL, derivedKey, NULL)) {
        return -3;  // Error initializing cipher context
    }

    return 0;  // Success
}

void cleanup_cipher(AES256Context *aes) {
    if (aes->ctx != NULL) {
        EVP_CIPHER_CTX_free(aes->ctx);
        aes->ctx = NULL;
    }
}
``` 
Note: This code uses OpenSSL library for AES and PBKDF2. You need to install OpenSSL before compiling this code. Also, you should add error checking for the return values of the functions that can fail.

