    [Route("api/[controller]")]
    public class ConfigController : Controller
    {
        private readonly IConnectionMultiplexer _redis;

        public ConfigController(IConnectionMultiplexer redis)
        {
            _redis = redis;
        }

        [HttpGet]
        public async Task<IActionResult> Get()
        {
            var db = _redis.GetDatabase();

            // Retrieve the latest configuration version from Redis
            var config = await db.StringGetAsync("latest-config");

            return Ok(config);
