Rust Daemon for Compiled Binary Verification and Reporting:
```rust
use std::fs;
use std::io::prelude::*;
use std::process::Command;
use std::thread;
use std::time::Instant;
use serde_json;
use sha2::{Sha256, Digest};
use std::net::TcpListener;

fn main() {
    // Listen for requests on a specified port.
    let listener = TcpListener::bind("127.0.0.1:8000").unwrap();

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                // Handle each connection concurrently.
                thread::spawn(move || {
                    let mut buffer = [0; 512];
                    stream.unwrap().read(&mut buffer).unwrap();

                    let resource_id: String = String::from_utf8_lossy(&buffer[..]).into_owned();

                    // Retrieve and verify the binary.
                    let start_time = Instant::now();
                    let output = Command::new("rustc")
                        .arg(format!["/path/to/sources/{}.rs", resource_id])
                        .output()
                        .unwrap();

                    // Calculate the SHA-256 checksum of the compiled binary.
                    let mut hasher = Sha256::new();
                    hasher.update(&output.stdout);
                    let sha_checksum = hasher.finalize();

                    // Log the results.
                    fs::write("/path/to/logs/compilation.json", serde_json::to_string(&CompilationLog {
                        start_time: start_time.elapsed().as_secs(),
                        sha256_checksum: format![sha_checksum],
                        stdout: output.stdout,
                        stderr: output.stderr,
                    }).unwrap()).unwrap();
                });
            },
            Err(e) => {
                println![Connection failed: {:?}", e);
            }
        };
    }
}
```

Please note that this is a simplified version and you would need to add error handling, retries, logging, dependency management etc. This code does not cover all the aspects of your request but should give an idea of how to start building such services. You may want to consider using frameworks like NestJS for AngularJS microservice or actix-web for Rust daemon, as they can make the development process easier and more efficient.
