        $this->providers[$name] = $provider;
    }
    // Add MFA services dynamically
    public function addMfaService($name, MFAServiceInterface $mfaService) {
        $this->mfaServices[$name] = $mfaService;
    }
    // Authenticate user with specific provider
    public function authenticateUser($providerName, $credentials) {
        if(!array_key_exists($providerName, $this->providers)) {
            throw new Exception('Provider not found');
        }
        $provider = $this->providers[$providerName];

        $tokenData = $provider->authenticate($credentials);

        if(!$tokenData) {
            return false;
        }
        // Store token data securely
        $user = User::findByTokenData($tokenData);

        if(!$this->checkMultiFactorAuthentication($user)) {
            throw new Exception('MFA failed');
        }

        return $user;
    }
    // Implement MFA based on configured service
    private function checkMultiFactorAuthentication(User $user) {
        $mfaService = $this->getPreferredMFAServiceForUser($user);
        if(!$mfaService) {
            throw new Exception('No preferred MFA service');
        }

        return $mfaService->authenticate();
    }
    // Get user's preferred MFA service
    private function getPreferredMFAServiceForUser(User $user) {
        $preferredMfa = $user->getPreferredMFA();
        if(!array_key_exists($preferredMfa, $this->mfaServices)) {
            throw new Exception('No MFA service for preferred method');
        }

        return $this->mfaServices[$preferredMfa];
    }
}
