```cpp
#include <chrono>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>

class AttackManager {
private:
    std::vector<std::pair<int, int>> attackCooldowns;  // pair of (attackId, cooldown)
    std::chrono::steady_clock::time_point lastAttackTime;

    std::mutex mtx;
    std::condition_variable cv;
public:
    void addAttack(int attackId, int cooldown) {
        std::lock_guard<std::mutex> lock(mtx);
        attackCooldowns.push_back({attackId, cooldown});
    }

    bool selectAttack() {
        std::unique_lock<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();
        for (auto& [attackId, cooldown] : attackCooldowns) {
            if (now - lastAttackTime >= std::chrono::seconds(cooldown)) {
                // Attack is ready to use. Perform the attack here and return true;

                lastAttackTime = now;  // Updating last attack time
                lock.unlock();
                return true;
            }
        }

        auto nextCooldownEnd = std::chrono::steady_clock::time_point::max();
        for (auto& [attackId, cooldown] : attackCooldowns) {
            auto cooldownEndTime = lastAttackTime + std::chrono::seconds(cooldown);
            if (now < cooldownEndTime && cooldownEndTime < nextCooldownEnd) {
                nextCooldownEnd = cooldownEndTime;
            }
        }

        if (nextCooldownEnd > now) {
            cv.wait_until(lock, nextCooldownEnd);
            return false;  // You can wait and then try to select again
        }
    }
};
```
This is a simple skeleton for an attack manager class where you add attacks with their cooldowns (in seconds). The `selectAttack()` function will block until the next attack is ready to use. 

