        });

        auth2Client = oAuth2Client;
    }
    return auth2Client;
}

app.post('/update/:filePath', async (req, res) => {
  const filePath = req.params.filePath; // replace with actual file path in cloud storage

  let data = await redisClient.get(`cache:${filePath}`);

  if (!data) {
    try {
      const oAuth2Client = await getOAuth2Client();

      // Fetch new data from external cloud storage
      const response = await axios({
        method: 'get',
        url: `https://storage.googleapis.com/${bucketName}/${filePath}`, 
        headers: {Authorization: `Bearer ${oAuth2Client.credentials.access_token}`},
      });

      data = response.data;
    } catch (error) {
      console.log(error);
      return res.status(500).json({error: 'Failed to fetch file from cloud storage'});
    }

    // Cache the data with a TTL of 60s
    redisClient.setex(`cache:${filePath}`, 60, data);
  }

  try {
      // Apply updates to file
      await fs.writeFile(`/path/to/local/config/files/${filePath}`, data, 'utf8'); 

      return res.status(200).json({message: 'Successfully updated configuration'});
  } catch (error) {
      console.log(error);
      return res.status(500).json({error: 'Failed to apply update to local file'});
  }
});
