```C++
#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <iostream>
#include <string>

namespace net = boost::asio;            // from <boost/asio.hpp>
namespace beast = boost::beast;        // from <boost/beast.hpp>
using tcp = net::ip::tcp;               // from <boost/asio/ip/tcp.hpp>

class AsyncHTTPRequest {
public:
    AsyncHTTPRequest(net::io_context& ioc, const std::string& host, 
                     const std::string& port)
        : resolver_(net::make_strand(ioc)) , socket_(ioc){

        // Save these for later use.
        host_ = host;
        port_ = port;
    }

    void SendAsyncRequest() {
       resolver_.async_resolve(host_, port_, beast::bind_front_handler(&AsyncHTTPRequest::onResolve, shared_from_this()));  
    }

private:
    tcp::resolver resolver_;
    beast::tcp_stream stream_;
    beast::flat_buffer buffer_; // (Must persist between reads)
    net::steady_timer timer_; 
    std::string host_, port_;

    void onResolve(beast::error_code ec, tcp::resolver::results_type results){
        if(ec) return fail(ec, "resolve");
        beast::get_lowest_layer(stream_).async_connect(results, 
            beast::bind_front_handler(&AsyncHTTPRequest::onConnect, shared_from_this()));  
    }

    void onConnect(beast::error_code ec, tcp::resolver::results_type::endpoint_type){
        if(ec) return fail(ec, "connect");
        stream_.async_handshake(ssl::stream_base::client, 
            beast::bind_front_handler(&AsyncHTTPRequest::onHandshake, shared_from_this()));  
    }

