    FilePathManager(BackendStorage& storage, Cache& cache, MetadataServiceClient& metadata) :
        storage_(storage),
        cache_(cache),
        metadata_(metadata){}

    void addFilePath(const std::string& path);
    void removeFilePath(const std::string& path);
    bool contains(const std::string& path);

private:
    BackendStorage& storage_;
    Cache& cache_;
    MetadataServiceClient& metadata_;
};

void FilePathManager::addFilePath(const std::string& path) {
    if (cache_.contains(path)) return;

    auto startTime = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < config.maxRetries; ++i){
        try {
            // Assume MetadataServiceClient has a async call metadata_.addFile(path)
            // and it returns immediately with future, not waiting for IO.
            auto result = metadata_.addFile(path).get(); 

            if (!result) throw std::runtime_error("Failed to add file in metadata service");

            // Assume BackendStorage has a async call storage_.addFile(path)
            // and it returns immediately with future, not waiting for IO.
            result = storage_.addFile(path).get(); 

            if (!result) throw std::runtime_error("Failed to add file in backend storage");

            cache_.insert(path); // Assume Cache has an insert method
        } catch (std::exception& e){
            auto elapsedTime = std::chrono::high_resolution_clock::now() - startTime;

            if (i == config.maxRetries - 1 || elapsedTime < config.maxBackoffInterval) {
                // Log the error and retry after a backoff interval
                int backOff = static_cast<int>(std::pow(2, i)) * 1000;
                std::this_thread::sleep_for(std::chrono::milliseconds(backOff));
            } else {
                // Log the error and fail
                throw e;
            }
        }
    }
}
```

