```javascript
// oauth.js - OAuth 2.0 Client
const { Issuer } = require('openid-client');

class OAuthClient {
    constructor(config) {
        this.config = config;
    }

    async authenticate() {
        const issuer = await Issuer.discover(this.config.issuer); 

        const client = new issuer.Client({
            client_id: this.config.clientId,
            token_endpoint_auth_method: 'none'
        });

        const tokenSet = await client.grant({
            grant_type: 'client_credentials', 
            scope: this.config.scope,
        });

        return tokenSet;
    }
}
```

```javascript
// apiClient.js - API Client with Authentication
const axios = require('axios');
const OAuthClient = require('./oauth');

class APIClient {
    constructor(config) {
        this.config = config;
        this.oauthClient = new OAuthClient(this.config);
    }

    async get(url, options) {
        const tokenSet = await this.oauthClient.authenticate();

        return axios.get(url, { 
            ...options,
            headers: { 
                'Authorization': `Bearer ${tokenSet.access_token}`,
                ...options?.headers
            }
        });
    }

    // Similarly for post, put, delete... methods
}
```
Please note that this is a very basic example and in real world scenario you would want to handle errors, retries, fallback mechanisms, concurrency issues etc. Also, OAuth2 authorization flow should be handled appropriately based on your use case. 

