1. Creating the cache system:
```c
#include <stdlib.h>
#include <string.h>

typedef struct CacheNode {
    char *key;
    void *value;
    struct CacheNode *next;
    struct CacheNode *prev;
} CacheNode;

CacheNode *cache = NULL;  // Initializes the cache to be empty
size_t cacheSize = 0;     // Initializes the current size of the cache to be zero
size_t maxCacheSize = 100000;  // Sets the maximum allowed size of the cache

void addToCache(char *key, void *value) {
    if (cacheSize >= maxCacheSize) {
        evictFromCache();  // Implement this function to remove nodes when cache is full
    }

    CacheNode *node = malloc(sizeof(CacheNode));
    node->key = key;
    node->value = value;
    node->next = cache;
    if (cache != NULL) {
        cache->prev = node;
    }
    cache = node;
    ++cacheSize;
}
```

