// Global mutex for thread-safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int N = 0; // user-defined parameter

// Function to initialize the library
void init(int size) {
    pthread_mutex_lock(&lock);
    if (list != NULL) {
        externalLoggingFramework.logError("List already initialized!");
        exit(1);
    }

    N = size;
    list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(list == NULL) {
        externalLoggingFramework.logError("Memory allocation failed!");
        exit(1);
    }
    pthread_mutex_unlock(&lock);
}

// Function to add an element to the list, handling out-of-memory conditions
void addElement(NFAPI_CRC_INDICATION_PDU_T* elem) {
    pthread_mutex_lock(&lock);

    // check memory availability and retry with exponential backoff if necessary
    for (int i = 0; i < N; ++i) {
        if(list[i] == NULL) {
            list[i] = elem;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // reallocate memory when the current allocation is full
    NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*) realloc(list, 2 * N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(temp == NULL) {
        externalLoggingFramework.logError("Memory allocation failed during reallocation!");
        pthread_mutex_unlock(&lock);
        return;
    }

    list = temp;
    N *= 2;
    list[N-1] = elem; // add element at the newly allocated memory location

    pthread_mutex_unlock(&lock);
}
```
