```rust
extern crate tokio;
use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use hyper::service::{make_service_fn, service_fn};
use hyper::{Body, Request, Response, Server};
use futures::future::FutureExt;

// User Profile Struct
pub struct UserProfile {
    pub id: i32,
    pub username: String,
    // More profile fields here...
}

// User Profile Manager Struct and Implementation
pub struct UserProfileManager {
    profiles: Arc<Mutex<HashMap<i32, UserProfile>>>,
}

impl UserProfileManager {
    pub fn new() -> Self {
        Self {
            profiles: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub async fn update_profile(&self, id: i32, profile: UserProfile) -> Result<(), ()> {
        let mut profiles = self.profiles.lock().await;
        match profiles.get_mut(&id) {
            Some(existing_profile) => {
                *existing_profile = profile;
                Ok(())
            }
            None => Err(()),
        }
    }

    pub async fn delete_profile(&self, id: i32) -> Result<(), ()> {
        let mut profiles = self.profiles.lock().await;
        match profiles.remove(&id) {
            Some(_) => Ok(()),
            None => Err(()),
        }
    }
}

// API Handler
pub async fn api_handler(req: Request<Body>, user_profile_manager: Arc<UserProfileManager>) -> Result<Response<Body>, hyper::Error> {
    match (req.method(), req.uri().path()) {
        // Handle PUT request for updating profile...
        (&hyper::Method::PUT, "/user/profile") => {
            let id: i32 = /* extract from request */;
            let profile: UserProfile = /* extract from request */;
            match user_profile_manager.update_profile(id, profile).await {
                Ok(()) => Ok(Response::new(Body::from("Profile updated"))),
                Err(_) => Err(hyper::Error::not_found()),
            }
        }
        // Handle DELETE request for deleting profile...
        (&hyper::Method::DELETE, "/user/profile") => {
            let id: i32 = /* extract from request */;
            match user_profile_manager.delete_profile(id).await {
                Ok(()) => Ok(Response::new(Body::from("Profile deleted"))),
                Err(_) => Err(hyper::Error::not_found()),
            }
        }
        _ => Err(hyper::Error::unsupported_media_type()),
    }
}

#[tokio::main]
async fn main() {
    let user_profile_manager = Arc::new(UserProfileManager::new());

    // Create service
    let make_svc = make_service_fn(move |req| api_handler(req, user_profile_manager.clone()));

    // Bind to address and start server
    let addr = ([127, 0, 0, 1], 3000).into();
    let server = Server::bind(&addr).serve(make_svc);

    if let Err(e) = server.await {
        eprintln![error] "Server error: {}" , e
    }
}
```
