import com.fasterxml.jackson.databind.ObjectMapper;

public class RemoteServerManagement {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    public void deleteFile(String serverUrl, String filePath) throws IOException {
        HttpURLConnection connection = null;

        try {
            URL url = new URL(serverUrl + "/delete?file=" + filePath);
            connection = (HttpURLConnection) url.openConnection();

            // Exponential backoff
            int delay = 1000; 
            int retryCount = 0;
            while (true) {
                try {
                    IOUtils.toString(connection.getInputStream(), "UTF-8");
                    break;
                } catch (IOException ex) {
                    if (retryCount >= 5) {
                        throw new IOException("Failed to delete file after 5 retries", ex);
                    }

                    retryCount++;
                    Thread.sleep(delay);
                    delay *= 2;
                }
            }
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    public void executeCommand(String serverUrl, String command) throws IOException {
        HttpURLConnection connection = null;

        try {
            URL url = new URL(serverUrl + "/execute?command=" + command);
            connection = (HttpURLConnection) url.openConnection();

            IOUtils.toString(connection.getInputStream(), "UTF-8");
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }
}
```

