3. Scaling and fallback: 
```c
void handle_message(int level, char *message) {
    LogMessage* new_msg = malloc(sizeof(LogMessage));
    if (new_msg == NULL) {
        // Error handling...
        return;
    }

    new_msg->level = level;
    new_msg->message = message;
    new_msg->next = NULL;

    pthread_mutex_lock(&lock);
    if (rear == NULL) {
        front = rear = new_msg;
    } else {
        rear->next = new_msg;
        rear = new_msg;
    }
    pthread_mutex_unlock(&lock);
}
