  public RealtimeRandomValueGenerator() {
    this.logger = new LoggerConfiguration()
        .WriteTo.Console()
        .CreateLogger();
  }

  public int GetInteger(int min, int max) {
    try {
      Random rnd = new Random();
      return rnd.Next(min, max);
    } catch (Exception ex) {
      logger.Error("Failed to generate integer: {@Reason}", ex);
      throw;
    }
