['Implementing this in C is complex as it doesn't have high-level abstractions or libraries available which can be used directly to achieve above requirements efficiently. However, here's an example of a TCP connection manager in C:

```c
#include <stdio.h>
#include <sys/socket.h>
#include <arpa/inet.h>  // for sockaddr_in and inet_addr()
#include <string.h>     // for memset
#include <unistd.h>     // for close()
#define BUFSIZE 1024

int main(void) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char buffer[BUFSIZE];
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation error");
        return -1;
    }
    memset(&serv_addr, '0', sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);  // port number
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {  // server address
        perror("address conversion error");
        return -1;
    }
    if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connection failed");
        return -1;
    }
    while (1) {
        printf("Enter message: ");
        fgets(buffer, BUFSIZE, stdin);  // read from standard input
        send(sockfd, buffer, strlen(buffer), 0);  // send to server
    }
    return close(sockfd);  // close the connection
}
```
This is a simple TCP client that connects to a server running on `127.0.0.1` and port `8080`, reads from standard input and sends it to the server. You can expand this into a more modular form to handle multiple databases and message queue services as well as handling various errors and implementing various strategies mentioned above. 

Implementing these in C is not recommended for large-scale applications due to its low level nature, lack of abstractions, manual memory management and potential security issues. For such scenarios, using a language with better support for concurrent programming (like Go or Rust), libraries/frameworks for cloud and database operations and tools for testing might be more beneficial. 

