using namespace std;

enum Status { ACTIVE, INACTIVE };

struct SessionContext {
    string appId;
    vector<char> apduBuffer;
    chrono::time_point<chrono::system_clock> initTime;
    chrono::time_point<chrono::system_clock> lastActivityTime;
    Status statusFlag;
};

class SessionManager {
private:
    map<string, shared_ptr<SessionContext>> sessions;
    mutex mtx;
    condition_variable cv;
public:
    void createSession(const string& appId) {
        lock_guard<mutex> lck(mtx);

        if (sessions.find(appId) == sessions.end()) {
            auto session = make_shared<SessionContext>();
            session->appId = appId;
            session->initTime = chrono::system_clock::now();
            session->statusFlag = ACTIVE;

            sessions[appId] = session;
        } else {
            // Handle existing session
        }
    }

    void deleteSession(const string& appId) {
        lock_guard<mutex> lck(mtx);

        if (sessions.find(appId) != sessions.end()) {
            sessions.erase(appId);
        } else {
            // Handle non-existing session
        }
    }

    void updateSessionActivityTime(const string& appId) {
        lock_guard<mutex> lck(mtx);

        if (sessions.find(appId) != sessions.end()) {
            sessions[appId]->lastActivityTime = chrono::system_clock::now();
        } else {
            // Handle non-existing session
        }
    }

    void changeSessionStatusFlag(const string& appId, Status newStatus) {
        lock_guard<mutex> lck(mtx);

        if (sessions.find(appId) != sessions.end()) {
            sessions[appId]->statusFlag = newStatus;
        } else {
            // Handle non-existing session
        }
    }

    shared_ptr<SessionContext> getSession(const string& appId) {
        lock_guard<mutex> lck(mtx);

        if (sessions.find(appId) != sessions.end()) {
            return sessions[appId];
        } else {
            // Handle non-existing session
            return nullptr;
        }
    }
};
