['Writing a full code block for this task is beyond the scope as it involves numerous components that need to be designed and implemented separately. However, I can outline an example of how you could start building your messaging platform using Java's built-in concurrency utilities, along with a rudimentary approach to logging in C++.

Java Messaging Platform:
```java
import java.util.concurrent.*;
import java.util.*;
import org.apache.http.client.config.RequestConfig;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;

public class MessagingPlatform {
    private ExecutorService executor = Executors.newFixedThreadPool(10); // Replace with your desired thread pool size
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(5);
    private CloseableHttpClient httpClient; 

    public MessagingPlatform() {
        RequestConfig requestConfig = RequestConfig.custom().setConnectTimeout(1000).build(); // Configure connect timeout to be 1 second
        this.httpClient = HttpClients.custom().setDefaultRequestConfig(requestConfig).build();
    }

    public void sendMessage(String message) {
        executor.execute(() -> {
            try {
                sendHttpRequestWithRetry(message);
            } catch (Exception e) {
                System.out.println("Failed to send message: " + e.getMessage());
            }
        });
    }

    private void sendHttpRequestWithRetry(String message) throws Exception {
        int maxAttempts = 3; // Replace with your desired number of retries
        for (int i = 0; i < maxAttempts; i++) {
            try {
                HttpGet request = new HttpGet("http://your.api/endpoint"); 
                CloseableHttpResponse response = httpClient.execute(request); // Replace with your actual HTTP request and handling of the response

                if (response.getStatusLine().getStatusCode() == 200) {
                    System.out.println("Message sent successfully.");
                    return;
                } else {
                    throw new Exception("API returned non-successful status code: " + response.getStatusLine().getStatusCode());
                }
            } catch (Exception e) {
                if (i == maxAttempts - 1) {
                    System.out.println("Failed to send message after " + maxAttempts + " attempts.");
                    throw e;
                } else {
                    Thread.sleep((long) Math.pow(2, i) * 1000); // Exponential backoff with jitter
                }
            }
        }
    }
}
```
