        INFO, WARNING, ERROR
    };

    void log(SeverityLevel severity, const std::string& message) {
        auto now = std::chrono::system_clock::now();
        auto timeString = std::ctime(&now);
        timeString[timeString.size() - 1] = '\0'; // Remove newline character from the end of string

        switch (severity) {
            case SeverityLevel::INFO:
                std::cout << "[INFO]: " << timeString << " - " << message << std::endl;
                break;
            case SeverityLevel::WARNING:
                std::cerr << "[WARNING]: " << timeString << " - " << message << std::endl;
                break;
            case SeverityLevel::ERROR:
                std::cerr << "[ERROR]: " << timeString << " - " << message << std::endl;
                break;
        }
    }
};
