                schemaValidator.validate(data);

                // Process the data (e.g., filter, aggregate, etc.)
            });
        }
    }
};

int main() {
    LogProcessor logProcessor;
    EventService eventService;

    // Start processing data in a separate thread
    std::thread processThread([&logProcessor, &eventService]() {
        logProcessor.processData(eventService);
    });

    // Wait for user input to stop the tool
    std::string input;
    while (std::getline(std::cin, input)) {
        if (input == "stop") {
            break;
        }
    }

    // Stop processing data
