public class FileTransferService {
    private String storageNode;

    public FileTransferService(String storageNode) {
        this.storageNode = storageNode;
    }

    public void transferFile(String filePath, String destinationIp) throws IOException {
        Socket socket = new Socket(destinationIp, 5000); // Assume port is 5000 for simplicity

        File file = new File(filePath);
        byte[] bytes = new byte[16 * 1024];
        InputStream in = new FileInputStream(file);
        OutputStream out = socket.getOutputStream();

        int count;
        while ((count = in.read(bytes)) > 0) {
            out.write(bytes, 0, count);
        }

        out.close();
        in.close();
        socket.close();
    }
}
