["Here is a high level outline of what the service might look like using Node.js and Express. This does not include full implementation, but gives an idea of how to structure the project.

Note: We assume you have experience with Node.js, ExpressJS, NLP libraries (like Natural), and databases (like MongoDB).

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const Natural = require('natural');
const redis = require('redis');
const axios = require('axios');

// assuming that the books are in an array for simplicity
const books = ['Genesis', 'Exodus', 'Leviticus', ...];
let bookFrequencyMap = {};  // key: book, value: count

let client = redis.createClient();
client.on('error', (err) => console.log(`Redis Error ${err}`));

const app = express();
app.use(bodyParser.json());

// API endpoint for processing text data and returning book counts
app.post('/books/process', async (req, res) => {
  const textData = req.body.text;

  // regular expression to match books from the Bible's Old Testament
  let regexBookFrequencyMap = {};
  for (let book of books) {
    let matches = textData.match(new RegExp('\\b' + book + '\\b', 'gi'));
    if (matches) {
      regexBookFrequencyMap[book] = (regexBookFrequencyMap[book] || 0) + matches.length;
    }
  }

  // NLP processing using natural library
  let tokenizer = new Natural.WordTokenizer();
  let tokens = tokenizer.tokenize(textData);

  for (let book of books) {
    let frequency = 0;

    for (let token of tokens) {
      if (token.toLowerCase() === book.toLowerCase()) {
        frequency++;
      }
    }

    // cache the results in Redis for performance optimization and caching
    client.get(book, function(err, reply) {
      if (!reply) {  // no cached data available
        bookFrequencyMap[book] = frequency;

        // cache the result with an expiry time of, say 1 hour
        client.setex(book, 3600, frequency);
      } else {
        bookFrequencyMap[book] = parseInt(reply) + frequency;
      }
    });
  }

  // Returning not just raw counts but also a summary of the most frequently mentioned books.
  let maxCount = 0, mostMentionedBook;
  for (let book in bookFrequencyMap) {
    if (bookFrequencyMap[book] > maxCount) {
      maxCount = bookFrequencyMap[book];
      mostMentionedBook = book;
    }
  }

  // Fetch additional metadata from a third-party API for more insights
  let apiResponse;
  try {
    const response = await axios.get('https://thirdpartyservice/api', {
      params: { book: mostMentionedBook },
    });
    apiResponse = response.data;

  } catch (error) {
    // handle network failure and retries here
    console.log(`Network error ${error}`);
  }

  res.json({ bookFrequencyMap, mostMentionedBook, ...apiResponse });
});

app.listen(3000, () => console.log('Server listening on port 3000'));
```
This code is a starting point and doesn't cover all the requirements in depth such as error handling, extensive testing, and many other aspects of production-grade software development. You would need to expand it for your use case, which is beyond the scope of this task.
"]

