class SwiftMailerPro {
    private $providers; // array of providers
    private $config; // configuration options

    public function __construct($config) {
        $this->config = $config;
        // Initialize provider objects based on config
    }

    public function addProvider($provider, $options = []) {
        if ($provider instanceof ProviderInterface) {
            $this->providers[get_class($provider)] = $provider;
        } else {
            throw new Exception("Invalid provider");
        }
    }

    public function sendEmail($email, $options = []) {
        $statuses = [];

        foreach ($this->providers as $provider) {
            $result = $provider->sendEmail($email, $options);

            if ($result->isSuccessful()) {
                return $result;
            } else {
                $statuses[] = $result;
            }
        }

        // If all providers fail to send the email, throw an exception or return combined status
    }
}
```
