        UserProfileManager {
            users: HashMap::new(),
        }
    }

    pub fn add_user(&mut self, user: User) -> Result<(), &'static str> {
        if self.users.contains_key(&user.id) {
            return Err("User already exists");
        }

        self.users.insert(user.id, user);
        Ok(())
    }

    pub fn update_user(&mut self, id: u32, username: String, password_hash: String) -> Result<(), &'static str> {
        if let Some(u) = self.users.get_mut(&id) {
            u.username = username;
            u.password_hash = password_hash;

            Ok(())
        } else {
            Err("User does not exist")
        }
    }

    pub fn delete_user(&mut self, id: u32) -> Result<(), &'static str> {
        match self.users.remove(&id) {
            Some(_) => Ok(()),
            None => Err("User does not exist"),
        }
