class DataFetcher:
    def __init__(self):
        self.APIs = []  # list of all APIs registered
        self.pool = {}  # connection pool

    def register_api(self, api):
        self.APIs.append(api)

    async def fetch_data(self):
        tasks = [self._fetch(api) for api in self.APIs]
        await asyncio.gather(*tasks)

    async def _fetch(self, api):
        try:
            # connect to the API, if not already connected using a connection pool
            conn = self.pool.get(api, None)
            if not conn:
                conn = await self._connect(api)
                self.pool[api] = conn

            data = await conn.fetch('SELECT * FROM some_table')
            return json.loads(data)

