['Below is a simplified implementation of the library. Note that it's not fully optimized for production use since this would involve several other considerations such as securely handling secrets, using a distributed cache system, managing network errors, etc. 

This code does not include all these aspects due to its complexity and length but should serve as a good starting point. 

```csharp
using System;
using System.Security.Cryptography;
using System.IO;
using System.Text;
using System.Threading;
using Newtonsoft.Json;
using NLog;

public class EncryptionService
{
    private static Logger logger = LogManager.GetCurrentClassLogger();
    private IAuthenticationService authService;

    public EncryptionService(IAuthenticationService authService)
    {
        this.authService = authService;
    }

    public byte[] Encrypt(byte[] plainText, string keyId)
    {
        try
        {
            var key = GetKey(keyId);

            using (var aesGcm = new AesGcm(key))
            {
                var nonce = RandomNumberGenerator.GetBytes(AesGcm.NonceByteSizes.MaxSize);

                var cipherText = new byte[plainText.Length];
                var tag = new byte[AesGcm.TagByteSizes.MaxSize];

                aesGcm.Encrypt(nonce, plainText, cipherText, tag);

                using (var combinedStream = new MemoryStream())
                {
                    combinedStream.Write(nonce);
                    combinedStream.Write(cipherText);
                    combinedStream.Write(tag);

                    return combinedStream.ToArray();
                }
            }
        }
        catch (Exception ex)
        {
            logger.Error("Encryption failed", ex);
            throw;
        }
    }

    public byte[] Decrypt(byte[] cipherText, string keyId)
    {
        try
        {
            var key = GetKey(keyId);

            using (var aesGcm = new AesGcm(key))
            {
                var nonceSize = AesGcm.NonceByteSizes.MaxSize;

                var nonce = cipherText[..nonceSize];
                var tagSize = AesGcm.TagByteSizes.MaxSize;
                var encryptedData = new ArraySegment<byte>(cipherText, nonceSize, cipherText.Length - nonceSize - tagSize).ToArray();
                var tag = new ArraySegment<byte>(cipherText, cipherText.Length - tagSize, tagSize).ToArray();

                var plainText = new byte[encryptedData.Length];
                aesGcm.Decrypt(nonce, encryptedData, tag, plainText);

                return plainText;
            }
        }
        catch (Exception ex)
        {
            logger.Error("Decryption failed", ex);
            throw;
        }
    }

    private byte[] GetKey(string keyId)
    {
        try
        {
            var token = authService.GetEncryptionKeyToken(keyId);

            return Convert.FromBase64String(token);
        }
        catch (Exception ex)
        {
            logger.Error("Failed to get encryption key", ex);
            throw;
        }
    }
}
```

This code uses `AesGcm` for encryption and decryption, assumes that the authentication service provides a base64-encoded string which it then converts into bytes using `Convert.FromBase64String` method. 

Each operation is wrapped in a try/catch block to handle exceptions gracefully and log any errors using NLog. 

For unit tests, you can use libraries such as MSTest or NUnit for testing the functionality of this class. You could test the encryption and decryption process along with error handling and logging functionality.
']

