        public static float GetRandomFloatInclusive(float min, float max)
        {
            lock (syncLock)
            {
                double range = max - min;
                double sample = getrandom.NextDouble();
                double scaled = sample * range;
                return (float)(scaled + min);
            }
        }

        // Error handling and retry mechanisms with exponential backoff for failed external data source requests 
        public static T GetRandomValueWithRetry<T>(Func<T> func) where T : IComparable
        {
            int retryCount = 3;

            while (retryCount > 0)
            {
                try
                {
                    return func();
                }
                catch (Exception e)
                {
                    Thread.Sleep(TimeSpan.FromSeconds(Math.Pow(2, retryCount))); // exponential backoff delay

                    if (--retryCount == 0)
                    {
                        Trace.TraceError("Failed to get value after retries: " + e.Message);
                        throw;
                    }
                }
            }

            return default(T); // or a fallback value, based on your requirements
        }
    }
}
