```cpp
#include <random>
#include <memory>
#include <vector>
#include <mutex>

namespace RandomSequences {
    class MTGenerator {
    public:
        explicit MTGenerator(int num_sequences) : mt_generators_(num_sequences), seeds_(num_sequences) {
            for (int i = 0; i < num_sequences; ++i) {
                mt_generators_[i] = std::make_unique<std::mt19937>(i);
            }
        }

        double get_random(int sequence_index) {
            if (sequence_index < 0 || sequence_index >= static_cast<int>(mt_generators_.size())) {
                throw std::out_of_range("Invalid sequence index");
            }

            std::lock_guard<std::mutex> lock(m_);
            return std::uniform_real_distribution<>(0.0, 1.0)(*mt_generators_[sequence_index]);
        }

        void reset_sequence(int sequence_index) {
            if (sequence_index < 0 || sequence_index >= static_cast<int>(seeds_.size())) {
                throw std::out_of_range("Invalid sequence index");
            }

            std::lock_guard<std::mutex> lock(m_);
            mt_generators_[sequence_index] = std::make_unique<std::mt19937>(seeds_[sequence_index]);
        }

    private:
        std::vector<std::unique_ptr<std::mt19937>> mt_generators_;
        std::mutex m_;
        std::vector<int> seeds_;
    };
}
```

