async function renderFooterScripts(scriptObjects) {
    const scriptTags = [];

    for (let i = 0; i < scriptObjects.length; i++) {
        const scriptObject = scriptObjects[i];

        // Generate nonce based on the key property
        const nonce = generateNonce(scriptObject.key);

        let content, src;
        if (scriptObject.src) {
            src = scriptObject.src;
        } else if (scriptObject.code) {
            // Sanitize and validate the code before rendering
            content = sanitizeAndValidateScript(scriptObject.code);
        }

        const attributes = `type="${scriptObject.type}" nonce="${nonce}" async=${scriptObject.async} defer=${scriptObject.defer}`;
        let tag = '';
        if (src) {
            // Dynamically load and insert script tags into the document footer
            tag = `<script ${attributes} src="${src}"></script>`;
        } else {
            tag = `<script ${attributes}>${content}</script>`;
        }

        try {
            scriptTags.push(tag);
        } catch (error) {
            console.log('Failed to generate and insert script tags', error);
        }
    }

    // Return the HTML string for a footer containing <script> tags
    return scriptTags.join('\n');
}
