    // Verify integrity with SHA-256 checksum
    let is_valid = verify_checksum(latest_binary);

    if !is_valid {
        log_error("Invalid binary version");

        // Recompile and restart process
        let result = process::Command::new("cargo")
            .arg("build")
            .spawn()?
            .wait();

        if result.success() {
            println_log("Binary recompiled successfully");
        } else {
            log_error("Failed to compile binary");
        }
    }
}
