```cpp
#include <iostream>
#include "websocketpp/config/asio_no_tls_client.hpp"
#include "websocketpp/client.hpp"

typedef websocketpp::client<websocketpp::config::asio_client> client;

using websocketpp::lib::placeholders::_1;
using websocketpp::lib::placeholders::_2;
using websocketpp::lib::bind;

// pull out the type of messages sent by our config
typedef websocketpp::config::asio_client::message_type::ptr message_ptr;

class IoTDataClient {
public:
    IoTDataClient() {
        // Set logging to be pretty verbose (everything)
        m_endpoint.set_error_channels(websocketpp::log::alevel::all);
        m_endpoint.set_access_channels(websocketpp::log::alevel::all ^ websocketpp::log::alevel::frame_payload);

        // Initialize ASIO
        m_endpoint.init_asio();
    }

    ~IoTDataClient() {
        // Disconnect just in case
        m_endpoint.stop();
    }

    void run(const std::string & uri) {
        websocketpp::lib::error_code ec;

        client::connection_ptr con = m_endpoint.get_connection(uri, ec);

        if (ec) {
            std::cout << "> Error: Could not create connection because: " << ec.message() << std::endl;
            return;
        }

        // Register handler callbacks
        m_endpoint.set_open_handler(bind(&IoTDataClient::onOpen, this, ::_1));
        m_endpoint.set_close_handler(bind(&IoTDataClient::onClose, this, ::_1));
        m_endpoint.set_fail_handler(bind(&IoTDataClient::onFail, this, ::_1));

        // Note that connect here only requests a connection. No actual network messages are
        // exchanged until the event loop starts running in the next line.
        m_endpoint.connect(con);

        // Start the ASIO io_service run loop
        // this will effectively block all threads, as this is where the client's WebSocket thread runs.
        m_endpoint.run();
    }

private:
    void onOpen(websocketpp::connection_hdl hdl) {
        std::cout << "> Connection established." << std::endl;
    }

    void onFail(websocketpp::connection_hdl hdl) {
        client::connection_ptr con = m_endpoint.get_con_from_hdl(hdl);
        std::cout << "> Error: Failed to connect to server: " << con->get_ec().message() << std::endl;
    }

    void onClose(websocketpp::connection_hdl hdl) {
        client::connection_ptr con = m_endpoint.get_con_from_hdl(hdl);
        std::cout << "> Connection closed: " << con->get_remote_close_code() << ", " 
                  << con->get_remote_close_reason() << std::endl;
    }

private:
    client m_endpoint;
};
```

This is a basic example of how you might start to ingest real-time sensor data using C++ and WebSocket. You'd need to extend this code to handle the various other requirements you have, such as data validation, concurrency, fault tolerance, etc. Also, keep in mind that you will need to install the WebSocket++ library which supports WebSocket communication over C++.
