['Implementing a full microservices platform in Rust with all these requirements is beyond a single code block, it will require multiple services interacting with each other and having their own database schemas. However, I can provide some skeleton Rust application that uses async-std to handle asynchronous tasks, JWT for token based authentication, reqwest for HTTP requests and rayon for parallel computation. This doesn't cover all your requirements but provides a starting point:

```rust
use async_std::task;
use jsonwebtoken::{decode, Algorithm, DecodingKey, Validation};
use reqwest::Error as ReqwestError;
use rayon::prelude::*;
use std::env;
use serde::Deserialize;
use thiserror::Error;
use tracing::info;

#[derive(Debug, Deserialize)]
struct Claims {
    sub: String,
    exp: usize,
}

#[derive(Error, Debug)]
enum JWTError {
    #[error("JWT Error: {0}")]
    Token(String),
}

async fn validate_jwt(token: &str) -> Result<Claims, ReqwestError> {
    let jwks_uri = env::var("JWKS_URI").unwrap();
    let resp = reqwest::get(&jwks_uri).await?;
    let jwk_set: jsonwebtoken::encode::Keys = resp.json().await?;

    for key in jwk_set.keys {
        if let Some(decoded) = decode::<DecodingKey>(&token, &key, &Validation::new(Algorithm::RS256)) {
            return Ok(decoded.claims);
        }
    }

    Err(ReqwestError::from_builder(reqwest::ResponseBuilder::new(), 0).unwrap())
}

#[task::blocking]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let token = env::var("JWT").unwrap();
    match validate_jwt(&token).await {
        Ok(claims) => info![.., %claims.sub],
        Err(_) => return Err("Invalid JWT".into()),
    }

    let nums: Vec<i32> = (1..=10_000).collect();
    let sum: i32 = nums.par_iter().map(|&num| expensive_compute(num)).sum();

    info![Computed sum: %sum];
    Ok(())
}

fn expensive_compute(num: i32) -> i32 {
    task::blocking::sleep(std::time::Duration::from_secs(1)).unwrap();
    num
}
```
This code will validate a JWT from environment variable and then perform an expensive computation in parallel. 

Please consider contacting me for more details or help on each part of the system, since building such a large system would require extensive planning and design work, and it's not feasible to provide all the code in one go.
']

