import java.util.*;

public interface NotificationBroker {
    void ingest(Event event);
}

public class SimpleNotificationBroker implements NotificationBroker {
    private final Map<String, List<Subscription>> subscriptions = new HashMap<>();

    public void addRule(SubscriptionRule rule) {
        // Implementation here...
    }

    @Override
    public void ingest(Event event) {
        String type = event.getType();
        if (subscriptions.containsKey(type)) {
            for (Subscription sub : subscriptions.get(type)) {
                // Send the event to all recipients in this subscription.
                for (Recipient recipient : sub.getRecipients()) {
                    recipient.receive(event);
                }
            }
