This is a basic example of how you can connect to Kafka and send a message using Python. You would need to extend this to suit your needs, including adding error handling, configuration options, retry logic etc. 

C Library (librdkafka):
The librdkafka library provides C bindings for the Apache Kafka client library. It is suitable both for application development and for integration into existing applications.
```c
#include <librdkafka/rdkafka.h>

int main() {
    char errstr[512];
    rd_kafka_t *rk;          /* Kafka handle */
    rd_kafka_topic_t *rkt;   /* Topic handle */
    const char *brokers = "localhost";  /* Broker list */
    const char *topic = "sample_topic"; /* Topic name */

    /* Create Kafka handle */
    rk = rd_kafka_new(RD_KAFKA_PRODUCER, NULL, NULL, 0);
    if (!rk) {
        fprintf(stderr, "%% Failed to create new producer\n");
        return 1;
    }

    /* Add brokers */
    if (rd_kafka_brokers_add(rk, brokers) == 0) {
        fprintf(stderr, "%% No valid brokers specified\n");
        return 1;
    }

    /* Create topic handle */
    rkt = rd_kafka_topic_new(rk, topic, NULL);
    if (!rkt) {
        fprintf(stderr, "%% Failed to create topic object\n");
        return 1;
    }

    /* Produce message */
    int produce_result = rd_kafka_produce(rkt, RD_KAFKA_PARTITION_UA, 0, "test message", strlen("test message"), NULL, 0, NULL);
    if (produce_result == -1) {
        fprintf(stderr, "%% Failed to produce to topic %s: %s\n", rd_kafka_topic_name(rkt), rd_kafka_err2str(rd_kafka_last_error()));
    } else {
        printf("Produced message\n");
    }

    /* Destroy topic */
    rd_kafka_topic_destroy(rkt);

    return 0;
}
```
In this C example, a Kafka producer is created and used to send a test message. Again, you would need to extend this to suit your needs including error handling, configuration options etc. 

