['Here is an overview of how you can design your `SecureDataHandler` library in C#. This would be a complex task that requires a comprehensive understanding of C# and encryption/decryption techniques. 

Please note this is just a basic skeleton implementation, detailed implementation depends heavily on the specific requirements of the project.

```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Extensions.Logging;

namespace SecureDataHandler 
{
    public class DataReceiver {
        private readonly ILogger<DataReceiver> _logger;
        private readonly ApiClient _apiClient;
        private readonly EncryptionProvider _encryptionProvider;

        public DataReceiver(ILogger<DataReceiver> logger, ApiClient apiClient, EncryptionProvider encryptionProvider) 
        {
            _logger = logger;
            _apiClient = apiClient;
            _encryptionProvider = encryptionProvider;
        }

        // DecryptAndParse method decrypts the data and parses it into an array of integers.
        public async Task<int[]> DecryptAndParse(string encryptedData, string key, string iv) 
        {
            try 
            {
                var decrypted = await _encryptionProvider.DecryptAsync(encryptedData, key, iv);
                return ParseToIntegers(decrypted);
            } 
            catch (Exception ex) when (ex is CryptographicException || ex is FormatException) 
            {
                _logger.LogError("Failed to decrypt and parse data: {0}", ex.Message);
                return null;
            }
        }

        // FindMax method finds the maximum integer in the array.
        public int? FindMax(int[] numbers) 
        {
            if (numbers == null || numbers.Length == 0) 
            {
                _logger.LogError("Failed to find max number: Input is empty or null");
                return null;
            }

            return numbers.Max();
        }

        // FilterEvenNumbers method filters out the even numbers from the array.
        public int[] FilterEvenNumbers(int[] numbers) 
        {
            if (numbers == null || numbers.Length == 0) 
            {
                _logger.LogError("Failed to filter even numbers: Input is empty or null");
                return null;
            }

            return numbers.Where(x => x % 2 == 0).ToArray();
        }

        // Helper method that parses the decrypted data into an array of integers, ignoring non-integer entries.
        private int[] ParseToIntegers(string[] decrypted) 
        {
            List<int> numbers = new List<int>();

            foreach (var entry in decrypted) 
            {
                if (Int32.TryParse(entry, out var number)) 
                {
                    numbers.Add(number);
                }
            }

            return numbers.ToArray();
        }
    }
}
```

This example does not include specific implementations for `ApiClient` and `EncryptionProvider` classes which are responsible for interacting with the external API to fetch data and decrypting it respectively, but they would likely use a similar approach as the example above. 

Additionally, this code does not cover aspects such as session token management or integration with distributed tracing systems, concurrent processing optimisation, rate limiting strategies, edge case handling, configuration via environment variables or a centralized configuration service and secure storage of encryption keys and IVs for simplicity reasons. These would require further implementation details to be provided, which may include specific libraries/tools/frameworks that are used in the project.

As this is an extensive task you should consider working with a team who has expertise in developing such a library or hiring professional developers.
