class AES_GCM {
public:
    AES_GCM(const std::string& key) {
        // Initialize AES context with the given key
        AES_set_encrypt_key((unsigned char*)key.c_str(), 256, &aesKey);
    }
    ~AES_GCM() {
        // Clean up when the object gets destroyed
        AES_set_encrypt_key(nullptr, 0, &aesKey);
    }

    std::string encrypt(const std::string& plaintext) {
        unsigned char in[AES_BLOCK_SIZE], out[AES_BLOCK_SIZE];
        AES_encrypt((unsigned char*)plaintext.c_str(), out, &aesKey);

        // Return encrypted data as a string (conversion might be needed)
        return std::string(reinterpret_cast<char*>(out), AES_BLOCK_SIZE);
    }

    std::string decrypt(const std::string& ciphertext) {
        unsigned char in[AES_BLOCK_SIZE], out[AES_BLOCK_SIZE];
        AES_decrypt((unsigned char*)ciphertext.c_str(), out, &aesKey);

        // Return decrypted data as a string (conversion might be needed)
        return std::string(reinterpret_cast<char*>(out), AES_BLOCK_SIZE);
    }
private:
    AES_KEY aesKey;
};
```
