['```rust
use std::fs;
use std::io::Result as IoResult;
use chrono::{Local, DateTime};
use log::info;
use std::env;
use std::thread;
use std::sync::Mutex;
use std::net::IpAddr;
use std::path::PathBuf;
use std::process::Command;
use std::io::Error as IoError;
use lazy_static::lazy_static;
use std::error::Error;
use regex::Regex;
use std::fs::MetadataExt;

fn get_current_time() -> String {
    let local: DateTime<Local> = Local::now();
    format![{}]} - {}", local.year(), local.month())
}

struct DataDirManager {
    mutex: Mutex<Option<PathBuf>>,
}

impl DataDirManager {
    fn new() -> Self {
        Self {
            mutex: Mutex::new(None),
        }
    }

    fn get_data_dir(&self) -> Option<PathBuf> {
        self.mutex.lock().unwrap()
    }

    fn set_data_dir(&self, path: PathBuf) {
        *self.mutex.lock().unwrap() = Some(path);
    }
}

lazy_static![static ref DATA_DIR_MANAGER: DataDirManager = DataDirManager::new();]

fn handle_dir_creation_and_env_var_setting(&mut self) -> IoResult<()> {
    let current_time = get_current_time();

    let env_data_dir = env::var("DATA_DIR").unwrap_or(String::from(""));
    if !env_data_dir.is_empty() {
        info![format![Checking directory {:?} for existence and writability,", env_data_dir]};

        let metadata = fs::metadata(&env_data_dir).unwrap();

        if metadata.exists() && metadata.permissions().readonly() {
            eprintln![format![Directory {} is not writable!]];
            return Err(IoError::new(ErrorKind::Other, "Directory is not writable"));
        } else if !metadata.is_dir() {
            eprintln![format![Path {} exists but it's not a directory!]];
            return Err(IoError::new(ErrorKind::Other, "Specified path exists but it's not a directory"));
        } else {
            info![format![Directory {} already exists and is writable.]};
            DATA_DIR_MANAGER.set_data_dir(PathBuf::from(env_data_dir));
        }
    } else {
        let dir_path = format!["/tmp/myapp_{}", current_time];
        let _ = Command::new("mkdir").args(&["-p".to_string(), &dir_path]).status().unwrap();

        info![format![Creating new directory {},]]};
        DATA_DIR_MANAGER.set_data_dir(PathBuf::from(dir_path));
    }

    env::set_var("DATA_DIR", DATA_DIR_MANAGER.get_data_dir().unwrap());
}
```
