use std::{fs, io};
use std::net::TcpStream;
use simple_logger;

fn main() {
    simple_logger::init().unwrap();

    loop {
        if let Err(e) = fetch_binary(&"127.0.0.1:34254".parse().unwrap()) {
            log::error("{}", e);
        }

        std::thread::sleep(std::time::Duration::from_secs(60));
    }
}

fn fetch_binary(addr: &str) -> io::Result<()> {
    let mut socket = TcpStream::connect(addr)?;

    let mut buf = Vec::new();
    io::copy(&mut socket, &mut buf)?;

    let hash_output =  hex::encode(Sha256::digest(&buf));
    log::info("Received binary with SHA-256 hash: {}", hash_output);

    Ok(())
}
