// Create Express server
const app = express();
app.use(express.json()); // Enable JSON parsing for request bodies

// Create a cache instance
const myCache = new NodeCache({ stdTTL: 100, checkperiod: 120 });

// Rate limiting middleware (adjust as needed)
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Load module dynamically
const loadModule = async (url) => {
    let response;
    try {
        if (!myCache.has(url)) {
            response = await Axios.get(url);
            myCache.set(url, response.data); // Cache the result for future use
        } else {
            console.log('Serving from cache');
            response = myCache.get(url);
        }
    } catch (err) {
        console.error(`Failed to load module: ${err}`);
        throw err;
    }
    const moduleCode = new Function("exports", "require", "module", response.data);
    let exports = {};
    moduleCode({}, require, module, exports);
    return exports;
};

// OAuth 2.0 authentication middleware (not included here due to complexity)

app.post('/executeModule', async (req, res) => {
    const { url } = req.body;
    if (!url) {
        return res.status(400).json({ error: 'Missing URL' });
    }
    try {
        // Load and execute module
        const moduleExports = await loadModule(url);
        console.log('Module executed successfully');
        res.send(moduleExports);
    } catch (err) {
        console.error('Failed to execute module', err);
        return res.status(500).json({ error: 'Failed to execute module' });
    }
});

