["Here's an outline of how you might implement this in JavaScript. For the sake of brevity, I'll be using `fetch` API for HTTP requests and promises for asynchronous operations. Error handling is done with try-catch blocks.

```javascript
async function renderFooterScripts(scriptObjects, maxParallelRequests = 10, externalSystemTimeout = 5000) {
    const nonce = btoa(scriptObjects[0].key); // Generate a base64 nonce based on key property

    async function loadScript(scriptObject) {
        let scriptTag;

        if (scriptObject.src) {
            // If src is provided, load it asynchronously with appropriate CORS and nonce attributes
            const script = document.createElement('script');
            script.nonce = nonce;
            script.async = true;
            script.crossOrigin = 'anonymous';
            script.src = scriptObject.src;

            scriptTag = script.outerHTML;
        } else if (scriptObject.code) {
            // If code is provided, use it directly in the script tag
            const script = document.createElement('script');
            script.nonce = nonce;
            script.textContent = scriptObject.code;

            scriptTag = script.outerHTML;
        } else {
            throw new Error(`Neither 'src' nor 'code' were provided for a script object`);
        }

        return scriptTag;
    }

    const promises = [];

    // Start loading scripts, up to maxParallelRequests at once
    for (let i = 0; i < Math.min(scriptObjects.length, maxParallelRequests); i++) {
        promises.push(loadScript(scriptObjects[i]));
    }

    const scriptTags = [];

    while (promises.length > 0) {
        try {
            // Wait for the next promise to resolve, add its result to our list
            const scriptTag = await Promise.race(promises);
            scriptTags.push(scriptTag);

            if (scriptObjects.length > maxParallelRequests) {
                promises.shift(); // Remove resolved promise

                // Start loading next script
                promises.push(loadScript(scriptObjects[maxParallelRequests + scriptTags.length - 1]));
            } else {
                promises.pop(); // No more scripts to load, remove the last promise
            }
        } catch (error) {
            console.log(`Failed to load a script: ${error}`);

            if (promises.length > 0) {
                promises.shift(); // Remove failed promise and try again with next one
            } else if (scriptTags.length < scriptObjects.length) {
                promises.push(loadScript(scriptObjects[scriptTags.length])); // Try to load the remaining scripts
            }
        }
    }

    return `<footer>${scriptTags.join('')}</footer>`;
}
```

This function loads up to maxParallelRequests scripts simultaneously, with each subsequent script loading after a previous one finishes. If a script fails to load, it is tried again until successful or all scripts have been tried. If there are more scripts remaining than can be loaded at once, they're left for later in the array and are retried when other scripts finish. 

This function also logs any errors that occur while loading scripts, so you can see what went wrong if something goes wrong.
"]

