```php
<?php
// Define an interface for all OAuth providers
interface OAuthProvider {
    public function authenticate($credentials);
}

class UserService {
    private $db; // Distributed database manager
    private $cache; // Cache manager
    private $rateLimiter; // Rate limiter service
    private $providers = []; // Array of OAuthProvider implementations

    public function __construct($db, $cache, $rateLimiter) {
        $this->db = $db;
        $this->cache = $cache;
        $this->rateLimiter = $rateLimiter;
    }

    // Register OAuth providers
    public function registerProvider(OAuthProvider $provider) {
        array_push($providers, $provider);
    }

    public function authenticate($credentials) {
        $this->rateLimiter->checkRateLimit(); // Check rate limit

        foreach ($providers as $provider) {
            try {
                $user = $provider->authenticate($credentials);

                if ($user != null) {
                    // If user is authenticated, store their data and tokens
                    $this->db->storeUserDataAndTokens($user); 
                    return $user;
                }
            } catch (NetworkFailureException $e) {
                $backoff = $this->handleNetworkFailure($e); // Exponential backoff
                $this->sleepWithExponentialBackoff($backoff);
            }
        }

        throw new AuthenticationFailedException("Unable to authenticate user");
    }

    public function getUserData($userId) {
        $cachedData = $this->cache->get('users:' . $userId);

        if ($cachedData != null) {
            return $cachedData; // Use cached data
        } else {
            $freshData = $this->db->getUserData($userId); 
            $this->cache->set('users:' . $userId, $freshData); // Cache fresh data
            return $freshData;
        }
    }

    private function handleNetworkFailure($exception) { /* ... */ }
    private function sleepWithExponentialBackoff($backoffTime) { sleep($backoffTime); }
}
?>
```
This code is a high-level outline. You would need to implement the database manager, cache manager, rate limiter service, and each specific OAuth provider class. These should be designed according to the Single Responsibility Principle in object-oriented design, meaning they each have one responsibility or job to do.
