```python
import pika
from pika import exceptions

class RabbitProducer:
    def __init__(self, hostname):
        self._params = pika.ConnectionParameters(host=hostname)

    def connect(self):
        try:
            self._connection = pika.BlockingConnection(self._params)
            self._channel = self._connection.channel()
        except exceptions.AMQPError as error:
            print("Caught a AMQP Error:", error)

    def publish_message(self, routing_key, message):
        try:
            self._channel.basic_publish(exchange='', 
                                        routing_key=routing_key, 
                                        body=message)
        except exceptions.AMQPError as error:
            print("Caught a AMQP Error:", error)
```
2. **Adaptive Message Broker Routing**: You can use RabbitMQ's capabilities for adaptive routing and deduplication. Here is an example of direct exchange type that routes messages based on the message routing key:
```python
class RabbitConsumer:
    def __init__(self, hostname):
        self._params = pika.ConnectionParameters(host=hostname)

    def connect(self):
        try:
            self._connection = pika.BlockingConnection(self._params)
            self._channel = self._connection.channel()
        except exceptions.AMQPError as error:
            print("Caught a AMQP Error:", error)

    def consume_messages(self, routing_key):
        try:
            self._channel.basic_consume(queue=routing_key, 
                                        on_message_callback=self.process_message, 
                                        auto_ack=True)
            self._channel.start_consuming()
        except exceptions.AMQPError as error:
            print("Caught a AMQP Error:", error)

    def process_message(self, ch, method, properties, body):
        # Process received message
```
