class ThreadPool {
public:
    void addTask(std::function<void()> task) {
        std::lock_guard<std::mutex> lock(m);
        tasks.push(task);

        // Start a new thread if we're not at maximum capacity
        if (threads.size() < maxThreads && !tasks.empty()) {
            threads.push_back(std::thread([this] { processTasks(); }));
