    }

private:
    void processTasks() {
        while (true) {
            std::function<void()> task;

            {
                std::lock_guard<std::mutex> lock(m);

                if (!tasks.empty()) {
                    task = tasks.front();
                    tasks.pop();
                } else {
                    return;
                }
            }

            // Execute the task
            task();
        }
    }

    std::queue<std::function<void()>> tasks;
    std::vector<std::thread> threads;
    size_t maxThreads;
    std::mutex m;
};
```
