```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

// Define NFAPI_CRC_INDICATION_PDU_T according to its requirements
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // fields
} NFAPI_CRC_INDICATION_PDU_T;

static const size_t MAX_CONNECTIONS = 1024;  // Configurable limit for UE connections
typedef struct PDUManager {
    atomic_int count;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_CONNECTIONS];
} PDUManager;

static int createPDUs(PDUManager *manager) {
    if (pthread_mutex_lock(&manager->lock)) return -1;  // Lock access to manager

    int count = atomic_load_explicit(&manager->count, memory_order_relaxed);
    if(count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&manager->lock);  // Unlock mutex before returning error
        return -2;  // Error: maximum number of PDUs reached
    }

    manager->list[count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->list[count]) {
        pthread_mutex_unlock(&manager->lock);  // Unlock mutex before returning error
        return -3;  // Error: memory allocation failed
    }

    atomic_fetch_add_explicit(&manager->count, 1, memory_order_relaxed);
    pthread_mutex_unlock(&manager->lock);  // Unlock mutex after successful PDU creation

    return count;
}
```
The `createPDUs` function creates a new `NFAPI_CRC_INDICATION_PDU_T` and adds it to the manager's list. It ensures thread-safe access by locking the mutex before each operation and incrementing the PDU count. If the maximum number of connections is reached or memory allocation fails, an appropriate error code is returned.

