```rust
use std::fs::File;
use std::io::Read;
use sha2::{Sha256, Digest};
use std::env;
use std::time::Instant;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 3 {
        println_err("Usage: verify <file> <sha256sum>");
        std::process::exit(1);
    }

    let file_name = &args[1];
    let sha256sum = &args[2].to_uppercase();

    println_info(&format_str("Starting binary verification for '{}'...", file_name));
    let start_time = Instant::now();

    // Read the file into memory.
    let mut file = match File::open(file_name) {
        Ok(f) => f,
        Err(_) => { println_err(&format_str("Failed to open '{}'", file_name)); std::process::exit(1); },
    };

    let mut buffer = Vec::new();
    match file.read_to_end(&mut buffer) {
        Ok(_) => (),
        Err(_) => { println_err(&format_str("Failed to read '{}'", file_name)); std::process::exit(1); },
    };

    // Compute the SHA-256 checksum.
    let mut hasher = Sha256::new();
    hasher.update(&buffer);
    let computed_checksum = format_str("{:X}", hasher.finalize());

    // Check if the checksums match.
    if computed_checksum != *sha256sum {
        println_err(&format_str("Checksum mismatch for '{}'", file_name));
        std::process::exit(1);
    } else {
        let elapsed = start_time.elapsed().as_secs();
        println_info(&format_str("Verified binary in {} seconds: '{}'", elapsed, file_name));
    }
}

fn format_str(fmt: &str, args: &str) -> String {
    format_args(&[args], fmt).unwrap()
}

fn println_info(message: &str) {
    println_colorful("32", message); // Green color code for info messages.
}

fn println_err(message: &str) {
    println_colorful("31", message); // Red color code for error messages.
}

fn println_colorful(color_code: &str, message: &str) {
    println_colorful_core(true, color_code, message);
}

// Helper function to enable/disable colorful printing based on environment variable setting.
fn println_colorful_core(enable: bool, color_code: &str, message: &str) {
    if enable {
        eprintln_colorful(color_code, message);
    } else {
        eprint_no_color(message);
    }
}
```
Please note this is just a basic example and the complete solution requires a lot more code including but not limited to API design, front-end development, database management, handling failures, service discovery etc. It's also recommended to use an existing framework or platform like AWS, Google Cloud Platform, Azure for production level application and services as it provides out of box features which can save development time and effort.
