namespace asio = boost::asio;
using tcp = asio::ip::tcp;
using error_code = boost::system::error_code;

class HttpRequestHandler {
public:
  explicit HttpRequestHandler(asio::io_context& ioContext) : resolver_(ioContext), stream_(ioContext) {}

  void Start(const std::string& server, const std::string& path) {
    CURL *curl = curl_easy_init();

    if (curl) {
      // Set URL and options.
      curl_easy_setopt(curl, CURLOPT_URL, (server + path).c_str());

      // Perform request and get response in 'response' string.
      curl_easy_perform(curl);

      // Cleanup.
      curl_easy_cleanup(curl);
    }
  }
};

int main() {
  asio::io_context ioContext;

  HttpRequestHandler handler(ioContext);
  handler.Start("https://api.example.com", "/path");

  // Run the I/O service on the thread pool.
  std::vector<std::thread> threads;
  for (auto i = 0; i < std::thread::hardware_concurrency(); ++i) {
    threads.emplace_back([&]() { ioContext.run(); });
  }

  // Wait for all threads to finish.
  for (auto& thread : threads) {
    if (thread.joinable()) {
      thread.join();
    }
  }

  return 0;
}
```
