// Define default config values
const DEFAULT_EXTERNAL_SYSTEM_TIMEOUT = 10; // 10 seconds
const DEFAULT_MAX_PARALLEL_REQUESTS = 5;

async function renderFooterScripts(scripts) {
    const externalSystemTimeout = scripts[0].externalSystemTimeout || DEFAULT_EXTERNAL_SYSTEM_TIMEOUT;
    const maxParallelRequests = scripts[0].maxParallelRequests || DEFAULT_MAX_PARALLEL_REQUESTS;

    const queue = new PQueue({ concurrency: maxParallelRequests });

    for (const script of scripts) {
        queue.add(async () => {
            try {
                // Fetch the script content, respecting CORS settings and handling errors
                let response = await fetch(script.src);

                // Check if response is OK
                if (!response.ok) throw new Error("HTTP error " + response.status);

                // Sanitize and validate the script content
                const text = sanitizeScriptContent(await response.text());

                // Create a script tag with the sanitized content and append it to document footer
                let element = document.createElement('script');
                element.type = 'text/javascript';
                element.async = true;
                element.src = text;
                document.body.appendChild(element);

            } catch (err) {
                // In case of error, fallback to default values or display a message to the user
                console.error('Script loading failed: ', err);
                let element = document.createElement('script');
                element.type = 'text/javascript';
                element.src = script.fallbackSrc || ''; // Default fallback source
                document.body.appendChild(element);
            }
        });
    }

    await queue.onIdle(); // Wait until all requests are finished
}
```
