#include <string>

// Snapshot data structure
struct Snapshot {
    std::string vmUUID;
    time_t timestamp;
    double diskUsage;
    enum State{RUNNING, PAUSED, TERMINATED}; 
    State state;
};

class StorageService {
public:
    virtual bool createSnapshot(const Snapshot& snapshot) = 0;
    virtual bool deleteSnapshot(const std::string& uuid) = 0;
    //... other operations
};

// Implementation of StorageService for a specific cloud storage service API 1.x
class CloudStorageServiceV1 : public StorageService {
public:
    bool createSnapshot(const Snapshot& snapshot) override;
    bool deleteSnapshot(const std::string& uuid) override;
    //... other implementations using V1.x APIs
};

// Implementation of StorageService for a specific cloud storage service API 2.x
class CloudStorageServiceV2 : public StorageService {
public:
    bool createSnapshot(const Snapshot& snapshot) override;
    bool deleteSnapshot(const std::string& uuid) override;
    //... other implementations using V2.x APIs
};

// Main class for managing snapshots
class SnapshotManager {
private:
    std::mutex mtx;
    std::unordered_map<std::string, StorageService*> storageServices; 
    std::vector<Snapshot> snapshots;
public:
    void addStorageService(const std::string& id, StorageService* service) {
        std::lock_guard<std::mutex> lock(mtx);
        storageServices[id] = service;
    }

    bool createSnapshot(const Snapshot& snapshot){
       for (auto &service : storageServices){
           if (!service.second->createSnapshot(snapshot)) {
               return false; // Handle failure in creating snapshot
           }
        }
        std::lock_guard<std::mutex> lock(mtx);
        snapshots.push_back(snapshot);  // Add to local cache after successful operation
        return true;
    }

    bool deleteSnapshot(const std::string& uuid){
       for (auto &service : storageServices){
           if (!service.second->deleteSnapshot(uuid)) {
               return false; // Handle failure in deleting snapshot
           }
        }

        std::lock_guard<std::mutex> lock(mtx);
        snapshots.erase(remove_if(snapshots.begin(), snapshots.end(), [&](auto &s) { return s.vmUUID == uuid; }), snapshots.end());  // Remove from local cache after successful operation
        return true;
    }
};
```

This is just a very basic skeleton of how you might start building this library, but note that it's not complete and doesn't cover all the requirements in your task. It also doesn't include any error handling or security measures which would be required for a real-world software project. 

