```C
#include <stdio.h>
#include <string.h>
#include <json-c/json.h>
#include <openssl/ssl.h>
#include <curl/curl.h>

#define TOKEN_ENDPOINT "https://oauth2.service.com/token"
#define CLIENT_ID "YOUR_CLIENT_ID"
#define CLIENT_SECRET "YOUR_CLIENT_SECRET"

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
    size_t new_len = s->len + size*nmemb;
    s->ptr = realloc(s->ptr, new_len+1);
    if (s->ptr == NULL) {
        fprintf(stderr, "realloc() failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(s->ptr+s->len, ptr, size*nmemb);
    s->ptr[new_len] = '\0';
    s->len = new_len;

    return size*nmemb;
}

void curl_request() {
    CURL *curl;
    CURLcode res;

    struct string s;
    s.len = 0;
    s.ptr = malloc(s.len+1);
    if (s.ptr == NULL) {
        fprintf(stderr, "malloc() failed\n");
        exit(EXIT_FAILURE);
    }
    s.ptr[0] = '\0';

    struct curl_slist *headers=NULL;
    headers = curl_slist_append(headers, "Content-Type: application/x-www-form-urlencoded");

    char postData[256];
    snprintf(postData, sizeof(postData), 
             "grant_type=client_credentials&client_id=%s&client_secret=%s", CLIENT_ID, CLIENT_SECRET);

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, TOKEN_ENDPOINT);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, postData);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", 
                    curl_easy_strerror(res));
        } else {
            json_object *jobj = json_tokener_parse(s.ptr);
            // Extract and validate token from JSON object here...

            json_object_put(jobj);
        }

        curl_easy_cleanup(curl);
    }

    free(s.ptr);
}
```
This is a very basic example of how you can use libcurl to make requests, parse JSON with json-c and handle SSL/TLS connections with OpenSSL in C. 

