import aiohttp
import asyncio
from hvac import Client
from functools import lru_cache

class LogAggregator:
    def __init__(self, vault_url='http://localhost:8200', log_services=None):
        self.log_services = log_services if log_services else []
        self.vault_client = Client(url=vault_url)

    @lru_cache(maxsize=1000)
    def get_api_key(self, service):
        try:
            return self.vault_client.read(f'secret/data/{service}')['data']['data']['api_key']
        except Exception as e:
            print(f"Error getting API key for {service}: {e}")
            return None

    async def fetch_logs(self, session, service):
        api_key = self.get_api_key(service)
        if not api_key:
            print("No API Key Found For Service")
            return []

        headers = {'Authorization': f'Bearer {api_key}'}

        try:
            async with session.get(f"https://{service}/logs", headers=headers) as resp:
                if resp.status == 200:
                    return await resp.json()
                else:
                    print(f"Error fetching logs from {service}: Status Code {resp.status}")
        except Exception as e:
            print(f"Error fetching logs from {service}: {e}")

    async def fetch_all_logs(self):
        async with aiohttp.ClientSession() as session:
            tasks = [self.fetch_logs(session, service) for service in self.log_services]
            return await asyncio.gather(*tasks, return_exceptions=True)

    def aggregate_logs(self):
        loop = asyncio.get_event_loop()
        logs = loop.run_until_complete(self.fetch_all_logs())
        for service, log in zip(self.log_services, logs):
            if isinstance(log, Exception):
                print(f"Failed to fetch logs from {service}")
            else:
                self.process_logs(log)

    def process_logs(self, logs):
        # process and store the logs
        pass
``` 

