    def ingest(self, data):
        if not isinstance(data, dict):
            return {"status": "error", "message": "Invalid data format"}

        stream_id = data['stream_id']
        schema = data.get('schema', {})

        if stream_id not in self.data_streams:
            self.data_streams[stream_id] = Stream(stream_id, schema)

        self.data_streams[stream_id].ingest(data['event'])

        return {"status": "success"}

    def get_processed_data(self, stream_id):
        if stream_id not in self.data_streams:
            return {"status": "error", "message": f"Stream with id {stream_id} does not exist."}

        return self.data_streams[stream_id].get_processed_data()

class Stream:
    def __init__(self, stream_id, schema):
        self.stream_id = stream_id
        self.schema = schema
        self.events = []

    def ingest(self, event):
        if not isinstance(event, dict):
            return {"status": "error", "message": "Invalid event format."}

        # Validate and filter the data based on the schema
