#include <pthread.h>
#include <stdlib.h>
#include <assert.h>

typedef struct NESRecord {
    // Add your fields here.
} NESRecord;

typedef struct NESList {
    pthread_mutex_t lock;
    NESRecord** data;
    size_t size, capacity;
} NESList;

NESList* createNESList() {
    NESList* list = (NESList*)malloc(sizeof(NESList));
    if (!list) return NULL;

    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resizeNESList(NESList* list) {
    assert(list != NULL);

    if (list->size < list->capacity) return;

    size_t newCapacity = list->capacity * 2;
    NESRecord** newData = realloc(list->data, newCapacity * sizeof(NESRecord*));

    if (!newData) return;

    list->data = newData;
    list->capacity = newCapacity;
}

void addToNESList(NESList* list, NESRecord* record) {
    assert(list != NULL);

    pthread_mutex_lock(&list->lock);
    resizeNESList(list);

    list->data[list->size++] = record;
    pthread_mutex_unlock(&list->lock);
}

void destroyNESList(NESList* list) {
    assert(list != NULL);

    for (size_t i = 0; i < list->size; ++i)
        free(list->data[i]); // Be sure to properly dispose of all dynamic data

    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}
``` 

