#define NFAPI_CRC_INDICATION_PDU_T_SIZE 50000

typedef struct {
    RX_UE_INFORMATION_TAG ueInfo;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfapiArray = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety.
atomic_int flag = 0;    // Atomic int to signal if memory is allocated or not.

void* allocateAndPopulateArray() {
    while(1) {
        // Try to lock the mutex.
        if (pthread_mutex_trylock(&mutex) == 0) {
            // Check if memory has already been allocated by another thread.
            if (atomic_load(&flag) == 2) {
                pthread_mutex_unlock(&mutex);
                return nfapiArray;
            }
            else if (atomic_load(&flag) == 0){
                // Allocate memory for the array.
                nfapiArray = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * NFAPI_CRC_INDICATION_PDU_T_SIZE);
                if (nfapiArray == NULL) {
                    // Handle memory allocation failure.
                    pthread_mutex_unlock(&mutex);
                    return NULL;
                }
                atomic_store(&flag, 1);   // Set flag to indicate that array is in-progress of allocation.
            }
            pthread_mutex_unlock(&mutex);   // Unlock mutex to allow other threads to allocate memory.
        }

        // Retrieve data from external source.
        RX_UE_INFORMATION_TAG ueInfo = retrieveDataFromSource();
        if (ueInfo != NULL) {
