                    // Populate RNTI and CRC_INDICATION_REL8_TAG as required.
                }
                atomic_store(&flag, 2);   // Set flag to indicate that array allocation is done.
            }
            pthread_mutex_unlock(&mutex); // Unlock mutex after array is populated.
        }
    }
}
