import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class HashUtil {
    private static final Logger logger = LoggerFactory.getLogger(HashUtil.class);
    private static final ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust according to your needs

    public static String computeHash(String input) throws Exception {
        if (input == null) throw new IllegalArgumentException("Input can't be null");

        synchronized (executor) {
            return executor.submit(() -> {
                try {
                    byte[] hash = MessageDigest.getInstance("MD5").digest(input.getBytes(StandardCharsets.UTF_8));
                    StringBuilder hexString = new StringBuilder();

                    for (byte b : hash) {
                        String hex = Integer.toHexString(0xff & b);
                        if(hex.length() == 1) hexString.append('0');
                        hexString.append(hex);
                    }

                    return hexString.toString();
                } catch (Exception ex) {
                    logger.error("Failed to compute hash", ex);
                    throw new RuntimeException(ex);
                }
            }).get(); // Waits for the computation and retrieves its result
        }
    }
}
```
