['This is a high-level architecture implementation of the `DynamicJSONHandler`. The details have been kept as abstract as possible to allow for flexibility in design and choice of tools/libraries.

```python
import json
import logging
from abc import ABC, abstractmethod
from threading import Lock
from config_service import ConfigService  # Implement your own service here

class AbstractFactory:
    @abstractmethod
    def process(self, data):
        pass

class FactoryRegistry:
    factories = {}
    lock = Lock()

    @classmethod
    def register_factory(cls, name, factory):
        with cls.lock:
            if not name in cls.factories:
                cls.factories[name] = factory

    @classmethod
    def get_factory(cls, name):
        return cls.factories.get(name)

class DynamicJSONHandler:
    def __init__(self):
        self.config = ConfigService()

    def load_schema(self, version):
        schema = self.config.get_schema(version)
        FactoryRegistry.register_factory(schema["name"], schema["factory"])

    def process_json(self, json_data, factory_name):
        try:
            data = json.loads(json_data)
        except ValueError as e:
            logging.error("Invalid JSON string", exc_info=True)
            return None

        factory = FactoryRegistry.get_factory(factory_name)

        if not factory:
            logging.error("No registered factory for given name")
            return None

        return factory().process(data)
```
To implement the actual JSON processing, you would create subclasses of `AbstractFactory` and register them with the `DynamicJSONHandler` using `load_schema()`.

