    char* sessionId;
    int length;
} NesRecord;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

char* append_if_within_limit(NesRecord *nes, int limit) {
    if (limit <= 0) {
        log_message("Error: Invalid size limit");
        return NULL; // Return special error indicator
    }

    pthread_mutex_lock(&lock);  // Lock to prevent race conditions

    char* result = malloc(sizeof(char) * (limit + 2));  // Additional space for '/' and null terminator
    if (!result) {
        log_message("Error: Memory allocation failed");
        return NULL; // Return special error indicator
    }

    if (nes->length <= limit) {
        sprintf(result, "%s/", nes->sessionId);  // Append '/' if length within limit
        log_message("Info: Length within limit");
    } else {
        strcpy(result, "EXCEEDED");  // Return predefined placeholder for exceeded length
        log_message("Warning: Length exceeded limit");
    }

    pthread_mutex_unlock(&lock);  // Unlock after operations are done

    return result;
}
```

In the above code, `append_if_within_limit` function takes a NES record and a size limit as input. It checks if the length of sessionId is within the specified limit and appends a '/'. If it's not, then "EXCEEDED" will be returned. The lock mechanism is implemented to ensure thread safety.

