```java
import java.util.*;
import java.util.concurrent.*;
import org.apache.http.client.methods.*;
import org.apache.http.impl.client.*;
import com.google.common.cache.*;
import io.reactivex.Observable;

public class ThirdPartyAPIService {
    private LoadingCache<String, String> cache;
    private CloseableHttpClient httpClient = HttpClients.createDefault();

    public ThirdPartyAPIService(LoadingCache<String, String> cache) {
        this.cache = cache;
    }

    public Observable<String> getDataFromAPI(String apiURL) {
        return Observable.fromCallable(() -> 
            Optional.ofNullable(this.cache.getIfPresent(apiURL))
                    .orElseGet(() -> callAPIAndUpdateCache(apiURL)))
                      .onErrorResumeNext(error -> fallbackStrategyForFailedAPICalls());
    }

    private String callAPIAndUpdateCache(String apiURL) throws Exception {
        HttpGet request = new HttpGet(apiURL);
        CloseableHttpResponse response = httpClient.execute(request);

        String data = EntityUtils.toString(response.getEntity());
        cache.put(apiURL, data);
        return data;
    }

    private Observable<String> fallbackStrategyForFailedAPICalls() {
        // Implement a strategy here for when the API call fails
        return Observable.just("Fallback Data");
    }
}
```
