['This problem is quite complex and requires a comprehensive solution spanning multiple technologies, which is beyond the scope of this platform. However, I can give you an example of how this might be implemented using Node.js with Express as backend framework and Redis for distributed caching. 

```javascript
// Import necessary modules
const express = require('express');
const axios = require('axios');
const asyncRedis = require("async-redis");
const bodyParser = require('body-parser');
const crypto = require('crypto');

// Initialize Redis client
const redisClient = asyncRedis.createClient(process.env.REDIS_PORT, process.env.REDIS_HOST);
redisClient.on("error", function(err) {
  console.log("Error " + err);
});

// Initialize Express app and apply body parser middleware
const app = express();
app.use(bodyParser.json());

// Token generation endpoint
app.post('/generateToken', async (req, res) => {
  try {
    const token = crypto.randomBytes(20).toString('hex'); // Generate random string as token

    // Encrypt token and store in Redis with expiration time
    await redisClient.setex(token, parseInt(process.env.TOKEN_LIFETIME), crypto.createHash('sha256').update(String(req.body.userId)).digest('hex')); 

    res.json({ token });
  } catch (err) {
    console.error(`Error generating token: ${err}`);
    return res.status(500).send();
  }
});

// Token validation endpoint
app.post('/validateToken', async (req, res) => {
  try {
    const encryptedUserId = await redisClient.get(req.body.token); // Fetch user ID from Redis

    if (!encryptedUserId) throw new Error('Invalid token');

    // Decrypt user ID and compare with request body's user id 
    const deciphered = crypto.createDecipher('aes192', process.env.SECRET_KEY);
    let decrypted = deciphered.update(encryptedUserId, 'hex', 'utf8');
    decrypted += deciphered.final('utf8');

    if (decrypted === req.body.userId) {
      return res.status(200).send(); // Valid token
    } else {
      throw new Error('Invalid token');
    }
  } catch (err) {
    console.error(`Error validating token: ${err}`);
    return res.status(401).send();
  }
});
```
Note: This is a basic example and does not include all the features you mentioned such as fallback strategies for external identity provider or retry logic, customization of token lifetimes, audit trail logging, testing, or detailed error handling. It also lacks performance optimization for cache usage such as setting an appropriate expiration time for keys in Redis, using pipelining when necessary to reduce round trips between client and server, etc. It's always recommended to consult with a security expert before implementing any kind of encryption and decryption logic.
']

