pub struct ExternalApi {
    client: Client<hyper::client::HttpConnector>,
}

impl ExternalApi {
    pub fn new() -> Self {
        let connector = hyper::client::HttpConnector::new();
        let client = Client::builder().build(connector);
        Self { client }
    }

    async fn get_template(&self, url: &str) -> Result<Value> {
        let result = self.client.get(url).await?;
        let body = hyper::body::to_bytes(result.into_body()).await?;
        Ok(serde_json::from_slice(&body)?)
    }
}

pub struct DynamicTemplate {
    api: ExternalApi,
    templates: HashMap<String, Value>,
}

impl DynamicTemplate {
    pub fn new() -> Self {
        let api = ExternalApi::new();
        Self {
            api,
            templates: HashMap::new(),
        }
    }

    pub async fn render_dynamic_template(&mut self, url: String) -> Result<Option<&Value>> {
        if let Some(template) = self.templates.get(&url) {
            return Ok(Some(template));
        }

        let result = self.api.get_template(&url).await?;
        self.templates.insert(url, result);
        Ok(self.templates.get(&url))
    }
}
```
