2) Implement a C program that reads a text file and prints the contents of each line in a comma-separated format, with the last field of each line being the average of the last two. Here's how you could start implementing this:

Note: This is very simplified and does not include all necessary error checking or handling edge cases. For a complete solution, additional code would be required.

```c
#include <stdio.h>  
#include <string.h> 
#define MAX_LINE_LEN 1024

int main() {
    FILE *file = fopen("input.txt", "r"); // Assume the input file is named "input.txt"

    if (file == NULL) {
        printf("Failed to open the file.\n");
        return -1; 
    }

    char line[MAX_LINE_LEN];

    while (fgets(line, MAX_LINE_LEN, file)) { // Read each line
        char *field = strtok(line, ","); // Tokenize the line by comma

        int i = 0; 
        double sum = 0.0;
        double values[2];

        while (field != NULL) { 
            if (i < 2) { 
                sscanf(field, "%lf", &values[i]); // Convert the field to a number
                ++i;
            } else {
                sum = values[0] + values[1]; // Calculate the sum of last two numbers
            }

            printf("%s, ", field); 
            field = strtok(NULL, ","); 
        }

        printf("%.2lf\n", sum / 2.0); // Print the average of the last two numbers
    }

    fclose(file);  
    return 0;
}
```
']

