["This is an advanced task that involves design, development, deployment, and performance optimization of a Node.js microservice with extensive consideration for system resilience, scalability, and efficiency. 

Below is a simplified outline of how to approach each of the points above:

```javascript
// Dependencies
const express = require('express');
const multer  = require('multer');
const axios = require('axios');
const util = require('util');
const fs = require('fs');
const crypto = require('crypto');
const Queue = require('bull');

// Initialize express app and multer for file handling
const app = express();
const upload = multer({ dest: 'uploads/' });

// Set up queue system with redis store
let checkSumQueue = new Queue('checksum validation', 'redis://127.0.0.1:6379');
let fileProcessingQueue = new Queue('file processing', 'redis://127.0.0.1:6379');

// Checksum validation process using environment variables for algorithm selection
const checkSumValidation = async (req, res) => {
  const checksumAlgo = process.env.CHECKSUM_ALGO || 'sha256';
  let hash = crypto.createHash(checksumAlgo);
  fs.createReadStream(req.file.path)
    .on('error', console.error)
    .pipe(hash)
    .once('finish', function() {
      return res.status(201).json({ checksum: hash.read() });
    })
};

// Numerical reduction engine with pluggable functions
const numericalReduction = (nums, funcName) => {
  const pluginFuncs = { sum: 'reduceSum', product: 'reduceProduct' };
  if(pluginFuncs[funcName]) return nums[pluginFuncs[funcName]]();
  else throw new Error('Invalid function');
};

// File upload handler. Add file to queue for processing and checksum validation
app.post('/upload', upload.single('file'), async (req, res) => {
    const job = await checkSumQueue.add({ path: req.file.path });
    job.on('completed', ()=>{
      fileProcessingQueue.add({ path: req.file.path, checksum: job.returnvalue })
    })
    res.status(200).json({ message: 'File received. Processing initiated.' });
});

// Start processing and validation jobs on demand 
checkSumQueue.process(async (job) => {
  return checkSumValidation(job);
})

fileProcessingQueue.process((job, done)=>{
    let nums = require(job.data.path); // Assume numbers are in an array format
    let checksumValid = job.returnvalue === job.data.checksum;
    if(!checksumValid){ 
      return done(new Error('Checksum mismatch'));
    }else{
      numericalReduction(nums, 'sum'); // For example
      done();
    }
});
```
Remember that this is a simplified code for illustrative purposes. Each function should be broken down into smaller units and have thorough unit tests written around it. Also, actual production-level code would involve proper error handling, logging/monitoring mechanisms, load balancing, etc. which are not covered in this simple outline.
"]

