typedef struct {
    char *path;
    void (*process)(struct FileData*);
} ThreadArgs;

typedef struct FileData {
    char *filename;
    char *extension;
    struct stat metadata;
    char *content;
    int size;
} FileData;

pthread_t threads[10]; // Simple thread pool
int num_threads = 0;

void* processFile(void* arg) {
    ThreadArgs *args = (ThreadArgs*)arg;
    FileData fileData;

    // Read metadata and content from file, fill the structure.
    stat(args->path, &fileData.metadata);
    FILE *f = fopen(args->path, "r");
    if (!f) {
        printf("Failed to open %s\n", args->path);
        pthread_exit(NULL);
    }
    // Read content of file into `fileData.content`
    fclose(f);

    // Call the user-defined processing function.
    (*args->process)(&fileData);

    return NULL;
}

void processDirectory(const char *dirPath, void (*processFile)(struct FileData*)) {
    DIR *d;
    struct dirent *dir;
    d = opendir(dirPath);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            char path[1024];
            sprintf(path, "%s/%s", dirPath, dir->d_name);

            // Check if directory or file.
            struct stat st;
            if (stat(path, &st) == 0) {
                if (S_ISDIR(st.st_mode)) {
                    // Recursive call to handle subdirectories.
                    processDirectory(path, processFile);
                } else if (S_ISREG(st.st_mode)) {
                    if (num_threads < 10) {
                        pthread_create(&threads[num_threads], NULL, processFile, &(ThreadArgs){path, processFile});
                        num_threads++;
                    } else {
                        // Wait for a thread to finish.
                        pthread_join(threads[num_threads % 10], NULL);
                        threads[num_threads % 10] = pthread_self();
                        num_threads++;
                    }
                }
            }
        }
        closedir(d);
    }
}

int main() {
    // Parse JSON config file and define processing function.
    void (*process)(struct FileData*) = NULL; // Define this based on the JSON configuration.

    processDirectory(".", process);

    // Wait for all threads to finish.
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
