    public void processProfiles(@RequestBody List<String> serializedUserProfile) {
        // Use ExecutorService for concurrency control
        ExecutorService executorService = 
                Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        serializedUserProfile.forEach(profile -> {
