async function uploadFile(filePath) {
    const pass = new RegExp('^[a-zA-Z0-9_ -]+\.(png|jpg|jpeg|gif|mp4|pdf|docx|txt)$');  // add more file types here.

    if (!pass.test(path.basename(filePath))) {
        throw new Error('Unsupported file type or format.');
    }

    const passSize = (stat) => {
        const maxSize = 1024 * 1024 * 5; // limit filesize to 5MB.
        if (stat.size > maxSize) throw new Error('File too large.');
        return true;
    };

    const fileStat = await fs.promises.stat(filePath);
    passSize(fileStat);

    let params = {
        Bucket: config.awsBucketName,
        Body:  fs.createReadStream(filePath),
        Key: path.basename(filePath), 
        ContentType: mime.lookup(filePath)
    };

    return s3.upload(params).promise();
}
