    connection = conn;
    connection.createChannel((errChnl, chnl) => {
        channel = chnl;
        channel.assertQueue(QUEUE_NAME, { durable: false });
    });
});

// Middleware to handle errors and log them
app.use((error, req, res, next) => {
    console.log('Error: ', error);
    res.status(500).json({ message: 'An error occurred' });
});

// Route for sending messages 
app.post('/sendMessage', async (req, res, next) => {
    const { userId, templateName, content } = req.body; // get from body or other source

    // Here we can use axios to call third-party API and handle errors
    let template;
    try{
        const response = await axios.get(`${THIRD_PARTY_URL}/templates/${templateName}`);
        template = response.data;
    } catch (error) {
        return next(error);
    } 

    // Now that we have user information and template, we can send the message to RabbitMQ queue for processing
    channel.sendToQueue(QUEUE_NAME, Buffer.from(JSON.stringify({userId, content, template})));
    res.status(201).json({message: 'Message sent'});
});

// Start the server 
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
```

