However, I can show you how to make a simple HTTP request using libcurl in C and parse JSON response. Here is a basic example:

```C
#include <stdio.h>
#include <string.h>
#include <curl/curl.h>

struct string {
  char *ptr;
  size_t len;
};

void init_string(struct string *s) {
  s->len = 0;
  s->ptr = malloc(s->len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "malloc() failed\n");
    exit(EXIT_FAILURE);
  }
  s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

int main() {
  CURL *curl;
  CURLcode res;

  curl_global_init(CURL_GLOBAL_DEFAULT);

  curl = curl_easy_init();
  if (curl) {
    struct string s;
    init_string(&s);

    curl_easy_setopt(curl, CURLOPT_URL, "https://example.com");

    /* we pass our 'writefunc' function */
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);

    /* pass our 'string' struct to the callback function */
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

    res = curl_easy_perform(curl);

    if (res != CURLE_OK) {
      fprintf(stderr, "curl_easy_perform() failed: %s\n",
              curl_easy_strerror(res));
    } else {
      printf("%s\n", s.ptr);
    }

    free(s.ptr);

    /* always cleanup */
    curl_easy_cleanup(curl);
  }

  return 0;
}
```
This code is a very basic example and doesn't include any error handling, rate limiting or other functionalities you might need for your project. I suggest looking into C libraries like libcurl (for HTTP requests) and Jansson (for JSON parsing). You may also want to look into concepts such as threads and sockets for network programming.
