import requests
from jsonschema import validate, ValidationError

class JSONSerializationFramework:
    def __init__(self):
        self.schemas = {} # This would be your schemas

    def register_schema(self, name, schema):
        if name not in self.schemas:
            self.schemas[name] = []
        self.schemas[name].append(schema)

    def validate(self, data, schema_name):
        for schema in reversed(self.schemas[schema_name]): # Most recent schemas first
            try:
                validate(data, schema)
                return True
            except ValidationError:
                continue
        return False
