#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/types.h>
#include <signal.h>
#include <assert.h>

// Semaphore type definition
typedef struct {
    sem_t sem;
} mysem_t;

int init_semaphore(mysem_t *s, int pshared, unsigned value) {
    return sem_init(&s->sem, pshared, value);
}

int operate_on_semaphore(mysem_t *s) {
    return sem_wait(&s->sem);
}

int cleanup_semaphore(mysem_t *s) {
    return sem_destroy(&s->sem);
}
```

