['The code given below is an abstract representation and does not cover all requirements mentioned above due to the complexity of each requirement. However, it provides a starting point for building such system in C:

```C
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

// A structure to hold connection information
typedef struct {
    int fd;
    char* backend;
} Connection;

// Array of connections
Connection* connections = NULL;
int numConnections = 0;
pthread_mutex_t lock;

void addConnection(int fd, char* backend) {
    pthread_mutex_lock(&lock);

    // Resize array to fit new connection
    connections = realloc(connections, sizeof(Connection) * (numConnections + 1));

    Connection conn;
    conn.fd = fd;
    conn.backend = backend;

    connections[numConnections] = conn;

    numConnections++;

    pthread_mutex_unlock(&lock);
}

void removeConnection(int fd) {
    pthread_mutex_lock(&lock);

    int indexToRemove = -1;

    // Find connection to remove
    for (int i = 0; i < numConnections; i++) {
        if (connections[i].fd == fd) {
            indexToRemove = i;
            break;
        }
    }

    if (indexToRemove != -1) {
        // Move last connection to freed slot
        connections[indexToRemove] = connections[numConnections - 1];

        // Resize array
        connections = realloc(connections, sizeof(Connection) * (numConnections - 1));

        numConnections--;
    }

    pthread_mutex_unlock(&lock);
}

void* handleConnection(void* fdPtr) {
    int fd = *((int*)fdPtr);

    // Simulate work with sleep
    sleep(5);

    removeConnection(fd);

    return NULL;
}

// Thread for handling new connections
void* acceptConnectionsThread(void* arg) {
    while (1) {
        int fd = /* Accept a new connection */;

        // Assign backend according to some criteria...
        char* backend = "PostgreSQL";

        addConnection(fd, backend);

        pthread_t thread;
        pthread_create(&thread, NULL, handleConnection, &fd);
    }

    return NULL;
}

int main() {
    // Initialize mutex
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        return 1;
    }

    pthread_t acceptThread;
