using System;
using System.Net.NetworkInformation;
using System.Threading;

namespace NetworkHealthMonitor
{
    public class NetworkHealthMonitor
    {
        private Timer _timer;
        private int _interval = 60000; // 1 minute in milliseconds
        private bool _isRunning = false;

        public void Start(int interval)
        {
            if (_isRunning) return;

            _interval = interval;
            _timer = new Timer(state => MonitorNetwork(), null, 0, _interval);
            _isRunning = true;
        }

        public void Stop()
        {
            _timer?.Dispose();
            _isRunning = false;
        }

        private void MonitorNetwork()
        {
            var reply = new Ping().Send("www.google.com");

            if (reply.Status != IPStatus.Success)
                Console.WriteLine($"Ping failed with status: {reply.Status}");
            else
                Console.WriteLine($"Reply from {reply.Address}: time={reply.RoundtripTime}ms");
        }
    }
}
```

This code creates a simple network monitor that pings "www.google.com" once every minute (or whatever interval you specify). It prints out the status of each ping attempt and if successful, it also prints out the round-trip time in milliseconds. You can enhance this by adding more detailed logging, error handling, and statistics gathering as per your requirements.
