['Here's a Python Flask application that serves as a simple User Authentication service which could be extended to meet your requirements. This is an oversimplified version and you would need to implement the mentioned features for production use. 

```python
from flask import Flask, jsonify, request, make_response
from werkzeug.security import generate_password_hash, check_password_hash
import uuid
import jwt
import datetime
from functools import wraps

app = Flask(__name__)

app.config['SECRET_KEY'] = 'thisissecret'
users = []

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.args.get('token') 

        if not token:
            return jsonify({'message' : 'Token is missing!'}), 403

        try: 
            data = jwt.decode(token, app.config['SECRET_KEY'])
            current_user = [x for x in users if x['id'] == data['id']][0]
        except:
            return jsonify({'message' : 'Token is invalid!'}), 403

        return f(current_user, *args, **kwargs)

    return decorated

@app.route('/register', methods=['POST'])
def signup():
    data = request.get_json()

    hashed_password = generate_password_hash(data['password'], method='sha256')

    new_user = {
        'id': str(uuid.uuid4()),
        'name': data['name'],
        'password': hashed_password,
    }

    users.append(new_user)

    return jsonify({'message': 'registered successfully!'})

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json() 

    user = [x for x in users if x['name'] == data['name']][0]

    if check_password_hash(user['password'], data['password']):
        token = jwt.encode({'id': user['id'], 'exp' : datetime.datetime.utcnow() + datetime.timedelta(minutes=30)}, app.config['SECRET_KEY'])

        return jsonify({'token' : token.decode('UTF-8')})

    return make_response('could not verify', 401, {'WWW.Authentication': 'Basic realm: "login required"'})

@app.route('/users', methods=['GET'])
def get_all_users():
    return jsonify({'users': users})

if __name__ == '__main__':
    app.run(debug=True)
```
This example uses the Flask framework for web server, JWT tokens for user authentication, and secure password hashing. This is a very basic implementation and does not include features such as data persistence or testing. For more complex features like data replication across multiple stores, you would need to integrate with other libraries/services or build custom solutions. 

This example also doesn't handle all the requirements for an authentication microservice (like handling MFA, account linking etc.), and also doesn't provide a REST API which could be used by third parties. You'd have to extend this service with additional endpoints for these features and integrate it with other services like OAuth providers.
']

