        Self { 
            users: HashMap::new(), 
        }
    }

    // Add a user to the profile manager. Returns true if added successfully.
    pub fn add_user(&mut self, id: u64, name: String) -> bool {
        if self.users.contains_key(&id) {
            false
        } else {
            let new_user = User { id, name };
            self.users.insert(id, new_user);
            true
        }
    }

    // Get a user from the profile manager. 
    // Returns None if the user doesn't exist in the database.
    pub fn get_user(&self, id: u64) -> Option<&User> {
        self.users.get(&id)
    }

    // Remove a user from the profile manager. 
    // Returns true if removed successfully.
    pub fn remove_user(&mut self, id: u64) -> bool {
        self.users.remove(&id).is_some()
    }
}
