const got = require('got'); // HTTP request library
const NodeCache = require("node-cache"); // In-memory caching library
const { pipeline } = require('stream'); // Streams library
const myCache = new NodeCache({ stdTTL: 100, checkperiod: 120 }); // Create in-memory cache with TTL and refresh period
const MAX_RETRIES = 5;
let requestCount = 0;

class ThemeConfigManager {
    constructor(apiUrl) {
        this.apiUrl = apiUrl;
    }

    async fetchThemeData() {
        const dataArray = [];

        for (let i = 0; i < MAX_RETRIES; i++) {
            try {
                // Handle rate limits, refresh tokens etc here

                const response = await got(this.apiUrl); 
                requestCount++;
                dataArray.push(response);

                if (requestCount % 100 === 0) { // Cache every 100 requests
                    myCache.set('data', dataArray, function (err, success) {
                        if (!err && success) console.log('Cached successfully');
                    });
                }
            } catch (error) {
                console.error(`Failed to fetch theme data due to ${error}, retrying...`);
                continue; // Retry mechanism
            }
        }

        throw new Error(`Failed to fetch theme data after ${MAX_RETRIES} attempts`);
    }

    async processData() {
        const cachedData = myCache.get('data');

        if (cachedData) return cachedData; // If cache exists, return from here
        else return this.fetchThemeData(); // Else fetch fresh data
    }
}

module.exports = ThemeConfigManager;
